(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c11"]=[{"id":"00011111","register_sub_id":"101","register_pk":"205218","name":"良寛記念館管理棟","kana":"りょうかんきねんかんかんりとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三島郡出雲崎町大字米田字十二社ノ上12-2他","lat":37.542432,"lng":138.688465,"geo_status":"db","era":"昭和39／昭和47・平成17改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積80㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0453","desc":"切妻造平入の平屋建で、敷地の前面側に建つ南北棟。北寄りに外部階段を設けて玄関とし、南側に来館者の受付機能と事務室を配する。南西隅以外の濡縁、緩やかな屋根と深い軒の出、開口部の縦格子が意匠上の特徴で、谷口の得意な現代の和風表現を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011111"},{"id":"00011110","register_sub_id":"101","register_pk":"205217","name":"良寛記念館展示棟","kana":"りょうかんきねんかんてんじとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県三島郡出雲崎町大字米田字十二社ノ上12-2他","lat":37.542378,"lng":138.687931,"geo_status":"db","era":"昭和36／昭和60・平成17改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積135㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0452","desc":"生誕地である出雲崎町において、良寛の遺墨などを展示するために建てられた記念館。設計は谷口吉郎。切妻造妻入平屋建で、東西北の各面に濡縁を巡らす。全体に建ちが低く、周辺環境とよく馴染む。谷口の特徴をよく表す鉄筋コンクリート造和風表現の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011110"},{"id":"00012890","register_sub_id":"101","register_pk":"504381","name":"桂湯","kana":"かつらゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県南砺市城端字大工町590他","lat":36.51420556,"lng":136.90153056,"geo_status":"db","era":"昭和5年頃／昭和37年・同41年・同52年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺及び金属板葺、建築面積155㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"16 － 147","desc":"旧城端町中心部の短冊形敷地に建ち、東から脱衣場棟、浴場棟、住居棟を並べる。脱衣場棟は木造二階建、正面銅板張の階境に蛇腹、軒に切妻破風を付し、中央の上部隅切の開口部に男女別出入口をまとめる。門前町の景観に彩りを添える洋風意匠のもと銭湯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012890"},{"id":"00004226","register_sub_id":"101","register_pk":"105216","name":"富山市郷土博物館（富山城）","kana":"とやましきょうどはくぶつかん（とやまじょう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"富山県","address":"富山県富山市本丸1-62","lat":36.69275781,"lng":137.21184698,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造4階建、瓦葺、建築面積725㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2004.07.23(平成16.07.23)","register_no":"16 － 0070","desc":"富山城跡南西寄り，二の丸から本丸への正面入口の石垣上に建つ。鉄筋コンクリート造４階建で，入母屋造の望楼をのせた３層４階からなる天守，２層２階の小天守状櫓など，城郭意匠で纏めている。地域の景観の核として，広く市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004226"},{"id":"00002030","register_sub_id":"101","register_pk":"103020","name":"廣野医院","kana":"ひろのいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県滑川市寺家町254","lat":36.76466469,"lng":137.33719009,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積59㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0057","desc":"住宅主屋北面に接続し，通り側を正面とした２階建の洋風建築。正面はクリーム色モルタル仕上げ壁面と鼠色洗出し仕上げの腰や隅部及び軒廻りで構成し，他面を下見板張りとする。正面妻飾に洋風の繊細な彫物や鬼板を用い，昭和初期の意匠をよくあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002030"},{"id":"00014475","register_sub_id":"101","register_pk":"513889","name":"石川県立能楽堂能舞台","kana":"いしかわけんりつのうがくどうのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市石引四丁目390-2","lat":36.55962778,"lng":136.663325,"geo_status":"db","era":"昭和6年／同46年移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積79㎡、橋掛り付","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"17 - 0311","desc":"兼六園南側に所在する能楽堂内にある舞台。入母屋造の典型的な能舞台で橋掛りを含み、観客席側は檜皮葺で背面杉皮葺。柱等の化粧材は台湾檜、足元の延石は戸室石を用い、時代性と地域性を示す。後座鏡板の松図は玉井敬泉画。加賀藩以来の能文化を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014475"},{"id":"00005814","register_sub_id":"101","register_pk":"106801","name":"上野家住宅旧診療所","kana":"うえのけじゅうたくきゅうしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市石引1-15-31","lat":36.55389317,"lng":136.67251679,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積65㎡","structure_material":"木造2階建","registered":"2006.10.19(平成18.10.19)","register_no":"17 － 0157","desc":"道路に面して建ち，桁行４間，梁間４間半，木造２階建，宝形造，桟瓦葺とする。外壁のモルタル塗に横目地を入れ，４本のピラスターを設け，レリーフや持送りを飾り，石造建築風のファサードを形成する。地方の近代化を示す指標となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005814"},{"id":"00012322","register_sub_id":"101","register_pk":"531646","name":"鴨ヶ浦塩水プール","kana":"かもがうらえんすいぷーる","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県輪島市輪島崎町","lat":37.40685,"lng":136.89791667,"geo_status":"db","era":"昭和10年頃／昭和24年・同30年頃改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"石造一部コンクリート造、面積345㎡","structure_material":"石造一部コンクリート造","registered":"2018.05.10(平成30.05.10)","register_no":"17-282","desc":"輪島市街近傍の鴨ヶ浦海岸にある水泳用の屋外プール。岩礁を縦25メートル横13メートルに削孔し、縁辺部をコンクリートで整える。南北に設けた取排水口から海水が自然に流出入する仕組み。立地特性を生かした類例稀なスポーツ施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012322"},{"id":"00014236","register_sub_id":"101","register_pk":"509626","name":"呉竹文庫主屋","kana":"くれたけぶんこおもや","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47885,"lng":136.47915833,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0304","desc":"手取川河口に所在する実業家が設立した私設図書館の主屋。木造平屋建、切妻造桟瓦葺で、外壁は真壁白漆喰塗り。内部は片廊下で、広縁と次の間を備える表座敷、仏間を備える奥座敷、床柱に白樺を用いた数寄屋風の造りの角座敷を配する。上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014236"},{"id":"00014237","register_sub_id":"101","register_pk":"509627","name":"呉竹文庫書庫及び閲覧室","kana":"くれたけぶんこしょこおよびえつらんしつ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47878333,"lng":136.47901389,"geo_status":"db","era":"大正4年頃／昭和3年増築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積173㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0305","desc":"手取川河口に所在する私設図書館の土蔵造書庫と木造閲覧室棟。二階建で屋根を一体とする。書庫は腰壁モルタル洗出仕上、戸口に掛子塗扉を開く。一階に書棚を設置、二階書斎は重厚な洋風意匠。閲覧室棟は一階蔵前を閲覧室、二階は数寄屋風の床付き座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014237"},{"id":"00014239","register_sub_id":"101","register_pk":"509629","name":"呉竹文庫茶室","kana":"くれたけぶんこちゃしつ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47895833,"lng":136.47931389,"geo_status":"db","era":"昭和18年頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0307","desc":"手取川河口に所在する私設図書館に実業家が建築した茶室。切妻造桟瓦葺で、三面に庇を回して土縁とし、土縁と茶室境は引違障子で開放的にする。茶室は三畳で床の脇に洞口で仕切る一畳大の小室を付す。壁に埋め込む呉竹を床柱にするなど床構えが独創的な茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014239"},{"id":"00014238","register_sub_id":"101","register_pk":"509628","name":"呉竹文庫土蔵","kana":"くれたけぶんこどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市湊町ヨ146他","lat":36.47895833,"lng":136.4792,"geo_status":"db","era":"明治22年頃／平成2年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"17 - 0306","desc":"手取川河口に所在する実業家が建設した元着物蔵。土蔵造二階建、切妻造平入、桟瓦葺で、外壁は西面を腰石張、他を下見板張とする。各階とも一室で板敷きとし、一階の戸口に鏝絵を施した掛子塗扉と、豪壮な鳥居枠を構える。図書館開設より前に建設した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014238"},{"id":"00015181","register_sub_id":"101","register_pk":"530605","name":"赤井家住宅新診療所","kana":"あかいけじゅうたくしんしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県吉田郡永平寺町清水8字村下出39-1","lat":36.07845833,"lng":136.40001111,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0251","desc":"主屋の南西に位置し、通りに南面して建つ診療所。木造平屋建寄棟造桟瓦葺で、外壁は軒までクリーム色モルタル吹付仕上。内部は玄関の東に薬局と診療室、北の廊下沿いに待合と休養室を配す。天井高と同高の軒を廻らし、縦長窓を並べるモダンな外観の診療所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015181"},{"id":"00015180","register_sub_id":"101","register_pk":"530604","name":"赤井家住宅病室棟（旧診療所）","kana":"あかいけじゅうたくびょうしつとう（きゅうしんりょうじょ）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町清水8字村下出39","lat":36.07861667,"lng":136.40001667,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"18 - 0250","desc":"主屋の西に南面して建つ、内・外科医院の病室棟で旧診療所。切妻造平入桟瓦葺で正面に玄関を付し、東南の渡廊下で主屋と接続する。内部は中廊下の東西に各２室を配し、北に洗面及び便所棟を付す。外壁下見板張とし、洋風意匠の外観が地域医療の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015180"},{"id":"00001187","register_sub_id":"101","register_pk":"102177","name":"井上歯科医院","kana":"いのうえしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市京町3-50","lat":35.90399929,"lng":136.16411982,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造２階建，瓦葺，建築面積62㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"18 － 0012","desc":"市の中心部に鎮座する総社大社の北方に位置する。明治３６年の大火後の建築で、土蔵造りとするが、外観意匠を洋風とする点に特徴がある。玄関回りのトスカナ式柱型や櫛型ペジメントなどの左官仕上げは石動芳次郎の仕事とされる。棟梁は地元の田倉藤太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001187"},{"id":"00004538","register_sub_id":"101","register_pk":"105528","name":"越前市武生公会堂記念館（旧武生公会堂）","kana":"えちぜんしたけおこうかいどうきねんかん（きゅうたけおこうかいどう）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市蓬莱町8-8","lat":35.90175846,"lng":136.16831828,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造地上2階一部4階地下1階建、建築面積601㎡、塔屋付","structure_material":"鉄筋コンクリート造地上2階一部4階地下1階建","registered":"2005.02.09(平成17.02.09)","register_no":"18 － 0036","desc":"南側及び東側が接道する敷地に南面して建つ。鉄筋コンクリート造地上２階建地下１階建で，南東部に６層の塔屋を配す。武生市では初期の本格的鉄筋コンクリート造で，塔屋のランドマーク性を強調する垂直線意匠や，楕円等を用いた１階玄関の意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004538"},{"id":"00008684","register_sub_id":"101","register_pk":"149405","name":"旧昭和会館（今庄地区公民館今庄分館）","kana":"きゅうしょうわかいかん（いまじょうちくこうみんかんいまじょうぶんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県南条郡南越前町今庄75字東中町6","lat":35.77287446,"lng":136.19741881,"geo_status":"db","era":"昭和6年／昭和62年改修","year":1931,"year_source":"converted","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積382㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0105","desc":"旧北国街道から少し東に入った位置に西面して建つ。鉄筋コンクリート造3階建で、西正面からは2階建に見える。中央にポーチを構え、左右対称の正面を造る。等間隔に柱型を現し、各階とも大きく窓を穿つ。簡明な外観のなか、柱頭飾りが効果的に配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008684"},{"id":"00006455","register_sub_id":"101","register_pk":"107438","name":"高鳥歯科医院診療所兼主屋","kana":"たかとりしかいいんしんりょうじょけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県小浜市小浜鹿島19","lat":35.493347,"lng":135.738983,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"18 － 0050","desc":"小浜漁港に向かう通りに東面して建つ。正面５間半、奥行５間の木造２階建で、２階南側３間分を診療所部とする。屋根は小屋根を戴くマンサード風とし、外部はモルタル洗出しで石目地を切って洋風に仕上げ、窓下等に煉瓦タイルを貼ってアクセントをつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006455"},{"id":"00012732","register_sub_id":"101","register_pk":"367635","name":"谷集会場","kana":"たにしゅうかいじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県勝山市北谷町谷87字中手外地6","lat":36.06088028,"lng":136.50062778,"geo_status":"db","era":"昭和28年／平成23年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、金属板葺、建築面積66㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"18 － 198","desc":"旧北谷郵便局南側の高台に牛首街道を挟んで西面して建つ。木造二階建、半切妻造鋼板葺妻入で、正面中央に切妻造の車寄を付す。外壁は下見板張で、正面二階に縦長窓を配し、大壁造の妻に三本の縦桟と鎧窓をあしらう。洒落た外観が特徴的な谷集落の象徴的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012732"},{"id":"00008670","register_sub_id":"101","register_pk":"149391","name":"深谷家住宅洋館","kana":"ふかやけじゅうたくようかん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県勝山市元町1-937他","lat":36.05946411,"lng":136.50109524,"geo_status":"db","era":"明治12年／明治前期増築","year":1879,"year_source":"converted","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積331㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0091","desc":"旧勝山城下に所在する。桁行14ｍ梁間12ｍ総2階建の東面に15畳の座敷が張り出す。起り屋根の寄棟造桟瓦葺で、2階の外壁を軒裏まで漆喰塗とし、街道に面する西面にはアーチ形の縦長窓を並べる。文明開化の世相を反映した元診療所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008670"},{"id":"00011947","register_sub_id":"101","register_pk":"211091","name":"福井市自然史博物館旧館（旧福井市立郷土博物館）","kana":"ふくいししぜんしはくぶつかんきゅうかん（きゅうふくいしりつきょうどはくぶつかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"福井県","address":"福井県福井市足羽上町147-1","lat":36.056693,"lng":136.20942,"geo_status":"db","era":"昭和27年／平成4年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積178㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2017.10.27(平成29.10.27)","register_no":"18-183","desc":"足羽山北東の山頂に建つ。鉄筋コンクリート造で、正面は玄関庇や各階の窓で水平性を、右端をカーテンウォールで垂直性を強調しながら、一階外壁は鉄平石張で積雪対策も講じる。階段廻りや屋上の天文台に旧規をよく留める。戦災・震災復興の記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011947"},{"id":"00008683","register_sub_id":"101","register_pk":"149404","name":"明治殿","kana":"めいじでん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県南条郡南越前町今庄76字南中町6-1","lat":35.7727132,"lng":136.19615803,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"converted","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0104","desc":"公園の後方に東面して建つ。入母屋造妻入銅板葺、桁行7.6ｍ梁間6.5ｍの木造平屋建。正面に唐破風造向拝を出す。方柱で舟肘木、二軒半繁垂木。正面は中央に桟唐戸をたて、両脇に独特の花頭窓を穿つ。風格ある外観のなか、兎毛通しに繊細な彫刻が配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008683"},{"id":"00001072","register_sub_id":"101","register_pk":"102062","name":"旧今井医院","kana":"きゅういまいいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県大月市初狩町中初狩221","lat":35.59596806,"lng":138.88083695,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造２階建，建築面積185㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"19 － 0032","desc":"甲州街道に面して建つ木造，モルタル仕上げ，陸屋根の建物で，コンクリート造に似た外観とする点に特徴がある。柱形や窓上の部分等は目地を入れて石造風にみせている点や，コーニスを模して軒に廻した幾何学的な連続装飾も，時代の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001072"},{"id":"00012332","register_sub_id":"101","register_pk":"531656","name":"旧加茂内科医院表門及び塀","kana":"きゅうかもないかいいんおもてもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南アルプス市小笠原255-1","lat":35.60919167,"lng":138.46691389,"geo_status":"db","era":"大正4年頃／昭和47年・平成12年移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、瓦葺、間口2.4m 塀 木造、瓦葺、総延長13m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-108","desc":"街道に面した敷地東面を区切る。表門は間口二・四メートルの腕木門で、切妻造桟瓦葺、肘木付の腕木で軒桁を受け、一軒疎垂木を配る。塀は真壁造で漆喰塗の腰板張とし、屋根を桟瓦葺とする。落ち着きのある表構えで、街道沿いの歴史的な景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012332"},{"id":"00012330","register_sub_id":"101","register_pk":"531654","name":"旧加茂内科医院診療所兼主屋","kana":"きゅうかもないかいいんしんりょうじょけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南アルプス市小笠原255-1","lat":35.60920556,"lng":138.46716667,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積117㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-106","desc":"旧小笠原宿内の短冊状の敷地中央に東面して建つ。二階建の入母屋造妻入で切妻起屋根の玄関を付ける。一階が診療所と居室、二階が座敷で、診療所の受付や待合室、診察室にはガラス窓を多用し、採光等に配慮する。大正期の地方診療施設の様相をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012330"},{"id":"00012331","register_sub_id":"101","register_pk":"531655","name":"旧加茂内科医院土蔵","kana":"きゅうかもないかいいんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県南アルプス市小笠原255-1","lat":35.60924444,"lng":138.46748333,"geo_status":"db","era":"大正4年頃／昭和20年頃移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-107","desc":"敷地奥に建つ。木造平屋建、切妻造桟瓦葺平入で、北面に戸口二箇所を開く。内部は、東室を土間、西室を板床とする。外壁はモルタル仕上で、鉄板張の板戸や鉄格子を入れた窓など防盗の配慮が窺える。近代診療施設における附属建物の有様を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012331"},{"id":"00001603","register_sub_id":"101","register_pk":"102593","name":"旧下山療院","kana":"きゅうしもやまりょういん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町下山1871","lat":35.41607373,"lng":138.44295176,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造3階建、瓦葺、建築面積131㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"19 － 0040","desc":"中廊下型平面からなる住宅兼用の病院建築。東側の街道に面して１階玄関，山側の背面に２階玄関を構える。もとは，２階南半に待合室・診療室・薬局を配し，１階各室を病室とする。身延山系東山麓の斜面の地形を利用した建築として間取や外観に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001603"},{"id":"00000043","register_sub_id":"101","register_pk":"101033","name":"甲府法人会館（旧甲府商工会議所）","kana":"こうふほうじんかいかん（きゅうこうふしょうこうかいぎしょ）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲府市中央4-12-21","lat":35.65711885,"lng":138.57183032,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積519㎡","structure_material":"鉄筋コンクリート造3階建","registered":"1996.12.20(平成8.12.20)","register_no":"19 － 0001","desc":"現存する山梨県最古の鉄筋コンクリート造のビルで，設計及び施工は内藤半次郎（内藤工業所）である。２階・３階を通した列柱の柱型をもつ外観の意匠に特徴がある一方，各種の機能を巧みに配した建築計画等に現代建築への萌芽がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000043"},{"id":"00009271","register_sub_id":"101","register_pk":"194064","name":"杉浦家住宅旧医院","kana":"すぎうらけじゅうたくきゅういいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64036586,"lng":138.53259886,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積145㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0069","desc":"敷地東側に建つ。東西棟の入母屋造二階建と南北棟の入母屋造平屋建からなる。建築面積一四五平方メートル、南に入母屋造の玄関を張出す。外壁は赤味を帯びた漆喰塗で腰はモルタル刷毛引き仕上げとして縦長窓を連続させる。内部に調剤室などを配する医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009271"},{"id":"00009270","register_sub_id":"101","register_pk":"194063","name":"杉浦家住宅主屋","kana":"すぎうらけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県中巨摩郡昭和町西条新田字村北850","lat":35.64032065,"lng":138.53237995,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積168㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"19 － 0068","desc":"敷地中央に建つ。寄棟造桟瓦葺で、建築面積一六八平方メートル。北、東面に屋敷蔵と旧医院への廊下や角屋を延ばす。南面に唐破風造の式台玄関を構える。建ちは高く、南面西半分から西面に下屋を張出して縁を廻し、二階は三面に窓を開ける開放的な構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009270"},{"id":"00000240","register_sub_id":"101","register_pk":"101230","name":"大正館倉庫（旧大正館）","kana":"たいしょうかんそうこ（きゅうたいしょうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県上野原市上野原1404","lat":35.62673666,"lng":139.11661567,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建，鉄板葺，建築面積232㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"19 － 0014","desc":"甲州街道旧上野原宿の東側に建つ映画館。昭和63年まで現役であったが、現在は倉庫となっている。木造２階建、下見板張りの建築であるが、ファサードはモルタル塗りとし、横連窓を配しており、インターナショナルスタイルの影響が見られる早い事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000240"},{"id":"00011503","register_sub_id":"101","register_pk":"210532","name":"𣇃米公民館","kana":"つきよねこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡富士川町𣇃米1237","lat":35.5719,"lng":138.44771111,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"19-0098","desc":"緩やかな斜面地に建つ。木造平屋建、入母屋造桟瓦葺で、南側正面には起り屋根の庇を設ける。南寄りに舞台を備える六〇畳大の集会室とし、北半には畳敷き数室を配する。公民館建築としては比較的大規模なもので、今日まで地域で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011503"},{"id":"00016381","register_sub_id":"101","register_pk":"536448","name":"上條産婦人科医院","kana":"かみじょうさんふじんかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市城東一丁目176-2","lat":36.23825278,"lng":137.97336667,"geo_status":"db","era":"大正4年／大正後期増築、昭和後期改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0675","desc":"市街地中心部の旧片端町に位置する産婦人科医院。全体雁行平面で南西に玄関ポーチを付し、一階中廊下の西は医院部、東は居住部とする。診療室は金属板装飾天井や腰タイル貼など上質な仕上。上下窓に櫛形ペディメントを付した洋風の外観が地域景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016381"},{"id":"00006598","register_sub_id":"101","register_pk":"107581","name":"旧草間歯科医院","kana":"きゅうくさましかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田2-29-4","lat":36.39660881,"lng":138.25729834,"geo_status":"db","era":"大正中期／平成16改修","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"20 － 0312","desc":"主屋の東方に位置し，西面して建つ。桁行３間，梁間２間半，土蔵造２階建，切妻造，桟瓦葺。小屋組は和小屋。外観は中塗仕上げで，出入口枠を丁寧に形づくり，前面に庇を設け，繰形を施した持送りを付ける。全体として簡素なつくりでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006598"},{"id":"00007027","register_sub_id":"101","register_pk":"108009","name":"旧鈴木歯科診療所（片岡山荘）","kana":"きゅうすずきしかしんりょうじょ（かたやまさんそう）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県北佐久郡軽井沢町大字軽井沢字西屋敷裏外167-15","lat":36.359276,"lng":138.632965,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積135㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"20 － 0333","desc":"敷地中央に南面して建つ旧別荘兼歯科診療所。切妻造鉄板葺の木造２階建、建築面積１３５㎡。食堂が拡張され、東側テラスが室内化されているが、全体として外観をよく残す。弁柄色系のペンキで塗装された鎧下見板の外壁に白色の窓枠のコントラストが映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007027"},{"id":"00016513","register_sub_id":"101","register_pk":"574875","name":"旧銭湯玉の湯","kana":"きゅうせんとうたまのゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県下伊那郡阿智村駒場1085-8","lat":35.44382778,"lng":137.74741361,"geo_status":"db","era":"大正前期／昭和中期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積105㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0685","desc":"集落中心部に東面して建つ銭湯。北半の二階建入母屋造は浴場で、内部に脱衣場と男女浴室を設け、外観は上下窓を配して、ドイツ壁の腰に橙色の洗出など洋風の意匠。南半の二階建切妻造は座敷棟で入母屋造玄関を構えた対照的な外観。山間集落を彩る戦前の銭湯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016513"},{"id":"00014003","register_sub_id":"101","register_pk":"508263","name":"旧松岡医院","kana":"きゅうまつおかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大手五丁目1319-5他","lat":36.23509444,"lng":137.9751,"geo_status":"db","era":"大正13年／平成29年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0590","desc":"松本城下に位置。木造二階建、寄棟造桟瓦葺。パラペットを立上げモルタルに目地を切り石造にみせ、縦長上下窓を並べ、幾何学装飾を付す。一階はホール・診療室の洋室と仏間等の和室を破綻なく並置する。二階は和室病室。装飾を凝らした洋風医院兼住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014003"},{"id":"00012530","register_sub_id":"101","register_pk":"367825","name":"旧松髙産婦人科医院表門及び塀","kana":"きゅうまつたかさんふじんかいいんおもてもんおよびへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田二丁目172-5、172-1","lat":36.394562,"lng":138.257034,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"表門 石造、間口2.2m 塀 石造及びコンクリート造、総延長15m","structure_material":"表門 石造","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0533","desc":"敷地前面にあり、大正館の玄関正面に表門を開き、東西に塀を延ばす。表門は花崗岩製、各頂部灯具付の門柱で、高さ間口とも2･2メートル。塀は成の低いコンクリート製で、柱と笠石に凝灰岩を用いる。丁寧なつくりで、洋式医院の気品ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012530"},{"id":"00012529","register_sub_id":"101","register_pk":"367824","name":"旧松髙産婦人科医院大正館","kana":"きゅうまつたかさんふじんかいいんたいしょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県上田市常田二丁目172-5、172-1","lat":36.394562,"lng":138.257034,"geo_status":"geocoded","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、金属板葺、建築面積33㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0532","desc":"上田市街東部の住宅地にある診療所兼住宅の診察棟。敷地東北辺に北面して建つ木造二階建、寄棟造鉄板葺で、玄関上に入母屋造の庇を付す。正面軒中央の半円アーチや二階窓上のペディメントなど大ぶりの意匠が特徴的な洋館で、地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012529"},{"id":"00015185","register_sub_id":"101","register_pk":"530609","name":"旧横内医院","kana":"きゅうよこうちいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県松本市大字島立字門田1867-1","lat":36.22650556,"lng":137.94171389,"geo_status":"db","era":"昭和7年／昭和40年代増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建一部地階付、瓦葺、建築面積171㎡","structure_material":"木造平屋建一部地階付","registered":"2024.12.03(令和6.12.03)","register_no":"20 - 0661","desc":"上高地線大庭駅の南方に位置し、敷地に東面して建つ医院兼主屋。正面は円柱を立て、起り付き入母屋造の玄関ポーチを付し、外壁モルタル塗洗出仕上、腰は石張風とする洋風医院で、背面に和風主屋を接続。診療室、薬局等の設えを残し、地域医療の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015185"},{"id":"00016383","register_sub_id":"101","register_pk":"536450","name":"小諸市立藤村記念館","kana":"こもろしりつとうそんきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県小諸市丁字本丸裏315-1","lat":36.32735833,"lng":138.41765,"geo_status":"db","era":"昭和33年／昭和45年増築","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0677","desc":"小諸城址懐古園内に南面して建つ島崎藤村の記念館。設計は谷口吉郎。木造平屋建、切妻造平入桟瓦葺。正面は格子を並べ、東半は吹放ちの石敷土間。内部の大半は展示室とし、玉砂利洗出仕上の土間とする。緩勾配屋根と簡素な和風意匠が公園内の景観と調和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016383"},{"id":"00001516","register_sub_id":"101","register_pk":"102506","name":"信濃教育会生涯学習センター","kana":"しなのきょういくかいしょうがいがくしゅうせんたー","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県安曇野市豊科高家796-3","lat":36.27211234,"lng":137.92843687,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、銅板葺、建築面積428㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"20 － 0035","desc":"県内の教育活動推進のために建設された旧信濃教育会館本館を長野市内から移築したもの。木造２階建，左右対称型で，正面中央に車寄をつけ，屋根窓付マンサード屋根を載せる。設計は宮原工務店の小林弥吉，施工は県内の官庁建築物を多く手がけた宮本長作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001516"},{"id":"00010141","register_sub_id":"101","register_pk":"197974","name":"下伊那教育会館","kana":"しもいなきょういくかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯田市仲ノ町303-1","lat":35.516186,"lng":137.830036,"geo_status":"db","era":"昭和13／昭和56改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積342㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0451","desc":"飯田城下の武家地にあたる仲ノ町に建つ木造二階建で、一階を事務室等、二階を講堂とする。正面屋根中央にマンサードの破風を見せて壁面を幾何意匠で飾り、左右にドーマー窓を配る。外壁は下見板張で縦長窓を連続させる。地域のランドマークとなる洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010141"},{"id":"00010142","register_sub_id":"101","register_pk":"197975","name":"下伊那教育会土蔵","kana":"しもいなきょういくかいどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県飯田市仲ノ町303-1","lat":35.516275,"lng":137.830213,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0452","desc":"会館の北背面に南面して建つ。桁行三間、梁間二間半とし、正面に下屋を設ける。漆喰塗の壁面は、鉢巻下方まで下屋柱とも海鼠壁とし、腰高の印象を持たせる。もとは幕末以降の教育資料を収蔵していた建物で、下伊那地域の教育史を語る上でも重要な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010142"},{"id":"00008992","register_sub_id":"101","register_pk":"162352","name":"諏訪市美術館（旧懐古館）","kana":"すわしびじゅつかん（きゅうかいこかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県諏訪市湖岸通り4-693-8","lat":36.04777658,"lng":138.11314298,"geo_status":"db","era":"昭和18年","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造2階建、瓦葺、建築面積440㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"20 － 0389","desc":"上諏訪温泉中心部に所在する片倉館の敷地内に建ち、建築面積４００㎡、木造二階建、入母屋造桟瓦葺である。内外ともコンクリート造風の大壁とし、全体を和風意匠でまとめる。洋風意匠の片倉館と相まって、諏訪湖畔独特の景観に貢献している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008992"},{"id":"00009951","register_sub_id":"101","register_pk":"196098","name":"諏訪市文化センター（旧北澤会館）","kana":"すわしぶんかせんたー（きゅうきたざわかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県諏訪市湖岸通り5-1018-1他","lat":36.04459981,"lng":138.11126238,"geo_status":"db","era":"昭和37","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積2239㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0445","desc":"中庭で劇場部分と会館部分を二分する平面を持つ。海鼠壁状の壁面仕上げや、格子風のルーバー、ベランダ手摺を菱形断面として高欄風に作るなど、鉄筋コンクリート造を主体としたモダニズム建築に、和風要素を付加した表現とする。吉田五十八の円熟期の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009951"},{"id":"00002922","register_sub_id":"101","register_pk":"103912","name":"高遠閣","kana":"たかとおかく","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県伊那市高遠町東高遠2295","lat":35.833481,"lng":138.063766,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積790㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"20 － 0106","desc":"町中心部，国史跡高遠城跡内に位置する，町民の集会場及び観光客の休憩施設として建設された施設。木造２階建，鉄板葺，入母屋造の大規模な造りで，千鳥破風，唐破風などを備えつつも，内部・開口部・車寄せなどに近代的要素を示す。伊藤文四郎の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002922"},{"id":"00003539","register_sub_id":"101","register_pk":"104529","name":"ふれあい館しらふじ（旧丸田医院）物置","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ものおき","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65374397,"lng":138.31448336,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺、建築面積41㎡","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0143","desc":"主屋と洋館に挟まれた中庭東にあり，もとレントゲン室であった。東西棟の切妻造，桟瓦葺，妻入，一部２階建の土蔵造という伝統的な形式になり，中庭側の下屋を廊下とし，主屋や洋館と連続する。地方における近代医院の建築構成を知る上で，貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003539"},{"id":"00003538","register_sub_id":"101","register_pk":"104528","name":"ふれあい館しらふじ（旧丸田医院）洋館","kana":"ふれあいかんしらふじ（きゅうまるたいいん）ようかん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県須坂市大字須坂32-1","lat":36.65364324,"lng":138.314392,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"20 － 0142","desc":"医院開業当時の診療棟で，中庭を挟んで主屋南側にたつ。木造平屋建，東西棟の寄棟造，桟瓦葺，妻入で，内部は４室になる。軒蛇腹は白漆喰塗，他を黒漆喰塗とした土蔵造で，柱型や長押型をあらわした外壁，小壁の額縁飾や窓枠の蛇腹など，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003538"},{"id":"00009952","register_sub_id":"101","register_pk":"196099","name":"南内田公民館","kana":"みなみうちだこうみんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県塩尻市大字片丘字若宮4156他","lat":36.15243426,"lng":137.98255891,"geo_status":"db","era":"昭和22／昭和23改修","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、瓦葺、建築面積264㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0446","desc":"道路沿いに東面して建つ木造の公民館。主体部は入母屋造二階建で、南北に張出す平屋部分も入母屋造として、各々東面に玄関を構え、風格ある外観を呈する。戦後新築されたものとして県内最古の公民館建築であり、地域住民の生活拠点として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009952"},{"id":"00016669","register_sub_id":"101","register_pk":"579153","name":"碌山美術館グズベリーハウス","kana":"ろくざんびじゅつかんぐずべりーはうす","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高5095-1","lat":36.343932,"lng":137.881836,"geo_status":"db","era":"昭和43年／平成9年改修","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"木造平屋建、石置板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0693","desc":"碌山美術館開館１０周年を記念して建てた展示室兼休憩室。払下げの枕木を積んで壁体とし、切妻屋根は石置板葺風モルタル塗の独特な外観。小屋はキングポスト・トラスとし、屋根東面に天窓を開ける。建設工事に地域の教員や学生が奉仕した山小屋風の展示施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016669"},{"id":"00016670","register_sub_id":"101","register_pk":"579154","name":"碌山美術館美術の倉","kana":"ろくざんびじゅつかんびじゅつのくら","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市穂高5095-1","lat":36.343781,"lng":137.881801,"geo_status":"db","era":"昭和45年","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"木造平屋建、石置板葺風モルタル塗、建築面積7.2㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0694","desc":"開館１０周年を記念して建てた収蔵庫。煉瓦造基礎の高床で払下げの枕木を積上げて壁体とする。切妻屋根は石置板葺風モルタル塗で、破風板上部に多数の十字架を飾る独特な外観。建設工事に地域の教員や学生が奉仕し、小規模ながら敷地景観を特徴付ける収蔵庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016670"},{"id":"00007991","register_sub_id":"101","register_pk":"128823","name":"碌山美術館碌山館","kana":"ろくざんびじゅつかんろくざんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県安曇野市穂高5095-1他","lat":36.34370221,"lng":137.88139659,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積116㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"20-0354","desc":"東面して建つＲＣ造平屋建で、外壁に焼き過ぎ煉瓦を貼る。切妻造妻入とし、主棟正面にポーチを付け、屋根はＳ字型瓦で葺き、銅板葺の尖塔を中心に建てる。側面には半円アーチ窓を連続させ、正背面にバラ窓を開ける。キリスト教会聖堂のイメージを反映した建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007991"},{"id":"00007994","register_sub_id":"101","register_pk":"128826","name":"旧飯地公民館（五毛座）","kana":"きゅういいじこうみんかん（ごもうざ）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県恵那市飯地町字中下185-1","lat":35.48202392,"lng":137.28950177,"geo_status":"db","era":"昭和26／昭和36・昭和40・昭和48頃・平成14改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積427㎡","structure_material":"木造2階一部地下1階建","registered":"2010.01.15(平成22.01.15)","register_no":"21-0173","desc":"南と西に接道し、南面して建つ。木造２階一部地下１階建、建築面積４２７㎡ 。南北棟の半切妻造桟瓦葺。正面は下見板張で、中央に寄棟屋根を付け入口ポーチとする。内部は花道を備えた舞台や、客席の平土間や桟敷席を設け、地芝居小屋として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007994"},{"id":"00009279","register_sub_id":"101","register_pk":"194072","name":"旧河合療院","kana":"きゅうかわいりょういん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県飛騨市古川町弐之町3-19","lat":36.2343085,"lng":137.18688551,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造一部土蔵造2階建、鉄板葺、建築面積426㎡","structure_material":"木造一部土蔵造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"21 － 0200","desc":"通りに南面して診療所を設け、後方に居住部、病室の順に配し、土間に土蔵を建てる。木造二階建、建築面積三六五平方メートル。大オーダー風の柱形をドイツ壁とし、各間に縦長の上下窓と幾何意匠をあしらう。古川の町並みに映える瀟洒な洋風意匠の医院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009279"},{"id":"00014013","register_sub_id":"101","register_pk":"508273","name":"旧須田歯科医院","kana":"きゅうすだしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県高山市桜町98","lat":36.14633611,"lng":137.26114444,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、鉄板葺、建築面積61㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"21 - 0292","desc":"高山市街江名子川右岸に建つ医院兼住宅。道路からやや引いて東面し、木造二階建、寄棟造平入で、東面中央を玄関とし張り出す。外壁は下見板張、南・東面に両開き縦長窓を開ける。内部は一階洋風、二階和風。町家の並ぶ高山にあって、大正期の洋風志向を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014013"},{"id":"00000825","register_sub_id":"101","register_pk":"101815","name":"旧林療院看護婦棟","kana":"きゅうはやしりょういんかんごふとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷789-1","lat":35.74951054,"lng":136.95879429,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造２階建，鉄板葺，建築面積41㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"21 － 0015","desc":"本館の左手に位置し，これと接続して建つ木造２階建の建物。内部は１，２階とも小部屋に区画され天井高も低い。もとの足軽長屋を改造したものといわれる簡素な佇まいの建屋で，全体に旧態を良く伝えている。地方医院の歴史を知る上で欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000825"},{"id":"00000773","register_sub_id":"101","register_pk":"101763","name":"旧林療院本館","kana":"きゅうはやしりょういんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷789-1","lat":35.74944611,"lng":136.95867468,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造２階建，瓦葺，建築面積116㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"21 － 0013","desc":"木造二階建の擬洋風の外観で知られた医院で，玄関ポ－チはイオニア式オーダーの円柱を立てる。軸組は伝統的な和風で仕上げるが，建物の隅や腰壁は石造風に見せるモルタル仕上げとし，上げ下げ窓の窓枠頂部に簡略のペジメントを付けるなどの工夫が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000773"},{"id":"00000826","register_sub_id":"101","register_pk":"101816","name":"旧林療院レントゲン棟","kana":"きゅうはやしりょういんれんとげんとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県郡上市八幡町島谷789-1","lat":35.74937086,"lng":136.95871838,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造２階建，鉄板葺，建築面積22㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"21 － 0016","desc":"本館棟の背後に建つ小規模な２階建の洋風建物で，１階は土蔵風になるが，全体として本館棟を意識した意匠にまとめる。岐阜県下でレントゲン施設が最も早く設置された例と伝え，地方都市で当時最新の医療が施されたことを知ることができる貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000826"},{"id":"00002042","register_sub_id":"101","register_pk":"103032","name":"旧堀谷医院","kana":"きゅうほりやいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県郡上市八幡町大手町804","lat":35.75163762,"lng":136.95659521,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積60㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"21 － 0036","desc":"旧郡上八幡城に近接する市街地に位置する。木造２階建，外壁コンクリート洗出しで，繰形の上に２階が張り出す。１階に大きなアーチ形窓，２階に上げ下げ窓を設け対照的な開口形式をとる。玄関ポーチの持送りと正面欄間に漆喰で意匠を凝らし見所とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002042"},{"id":"00000048","register_sub_id":"101","register_pk":"101038","name":"名和昆虫博物館","kana":"なわこんちゅうはくぶつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市千畳敷大道西308-1","lat":35.43316309,"lng":136.77316051,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積183㎡","structure_material":"煉瓦造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"21 － 0001","desc":"桟瓦葺切妻屋根の煉瓦造建築で，ギリシャ神殿風屋根妻を模した車寄せ玄関と，奈良唐招提寺の解体修理時にもらい受けた３本の丸柱が意匠上の特徴である。設計は当時名古屋高等工業学校の校長であった武田五一であり，彼の作風を示す建物の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000048"},{"id":"00001774","register_sub_id":"101","register_pk":"102764","name":"旧五十嵐歯科医院","kana":"きゅういがらししかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市清水区蒲原3-23-3","lat":35.11981034,"lng":138.60328787,"geo_status":"db","era":"大正3頃／昭和16増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"22 － 0070","desc":"旧東海道筋に建つ木造２階建の洋風建築。在来の町屋の間取りを残しつつ，外観と内装一部が改造された。寄棟造瓦葺で硝子窓の開口部を広くとり，その他壁面を下見板張とし，玄関及び増築された西棟正面に軒板飾を付ける。地元の大工吉田源吉の設計と伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001774"},{"id":"00008695","register_sub_id":"101","register_pk":"149416","name":"旧木村家住宅主屋","kana":"きゅうきむらけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県賀茂郡河津町峰603","lat":34.75514705,"lng":138.98288554,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部平屋建、瓦葺、建築面積304㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"22 － 0177","desc":"北に川を望む庭園内に建つ。木造2階1部平屋建、建築面積三304㎡。基礎まわりをタイル貼とし、壁はベージュ色のモルタル洗出し仕上げ、緑釉の桟瓦を葺き、所々に出窓を付け、ポーチなどに節のある磨丸太を使う。抑制のきいた意匠になる別荘建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008695"},{"id":"00008694","register_sub_id":"101","register_pk":"149415","name":"旧順天堂田中歯科医院診療所兼主屋","kana":"きゅうじゅんてんどうたなかしかいいんしんりょうじょけんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県富士市吉原3-3510-6","lat":35.16418492,"lng":138.68615879,"geo_status":"db","era":"明治中期／大正14年移築増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積187㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"22 － 0176","desc":"通りに西面する敷地の東寄りに建つ。洋館と和館からなり、屋根は鉄板葺、建築面積187㎡。洋館は2階1部平屋建で、屋根寄棟造とし、6角形平面でドーム型の屋根や、急勾配の屋根を付設する。下見板張で、縦長の上下窓を配する。町中の洋館として親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008694"},{"id":"00005276","register_sub_id":"101","register_pk":"106264","name":"神山復生病院事務所棟","kana":"こうやまふくせいびょういんじむしょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県御殿場市神山1910-8","lat":35.23858521,"lng":138.92306269,"geo_status":"db","era":"明治中期／昭和中期増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積72㎡、地下室付","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"22 － 0107","desc":"病院敷地のほぼ中央に南面して建つ。切石積の基礎にのる木造２階建で，地下１階を設け，屋根は鉄板葺とし，正側面に下屋庇を付ける。正面中央入口には切妻造の玄関ポーチを突出し，外壁は下見板張とする。開院当初の歴史的な景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005276"},{"id":"00013400","register_sub_id":"101","register_pk":"368485","name":"ＹＭＣＡ東山荘齊藤記念館","kana":"わいえむしーえーとうざんそうさいとうきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県御殿場市深沢字丸嶽2013-5","lat":35.28866944,"lng":138.95636667,"geo_status":"db","era":"昭和40年／平成2年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造地上2階一部地下1階建、建築面積632㎡","structure_material":"鉄筋コンクリート造地上2階一部地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"22 － 0288","desc":"敷地西寄りに建つ、南北に長い平面の鉄筋コンクリート造で、中央南寄りに玄関を張出す。ラーメン構造を現し、水平軒を強調した立面などモダニズムの特徴を示しつつ、二階屋根に勾配をつけ、玄関ホールなど要所を自然石貼とするなど、内外観に変化をもたせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013400"},{"id":"00013399","register_sub_id":"101","register_pk":"368484","name":"ＹＭＣＡ東山荘フィッシャー館","kana":"わいえむしーえーとうざんそうふぃっしゃーかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"静岡県","address":"静岡県御殿場市東山字池上1049-3他","lat":35.28942222,"lng":138.95775833,"geo_status":"db","era":"昭和25年／平成22年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積136㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"22 － 0287","desc":"西面し、広場越しに富士山を望む。平屋建の応接室棟と居室棟を渡廊下で接続し、前者は暖炉を備えた応接室と居間、後者は和室と水回りからなる。両棟とも開口を広く取り、外壁は腰高に下見板を張り、小壁と水平な軒裏を漆喰塗とする。落ち着いた佇まいの施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013399"},{"id":"00001912","register_sub_id":"101","register_pk":"102902","name":"旧井上家住宅西洋館","kana":"きゅういのうえけじゅうたくせいようかん","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊田市平戸橋町波岩86-100","lat":35.1225478,"lng":137.19002514,"geo_status":"db","era":"明治10代","year":1877,"year_source":"converted","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"23 － 0047","desc":"博覧会の貴賓館として名古屋に建造されたと伝わる。その後用途を変えつつ，移築･増改築された。木造2階建，寄棟造桟瓦葺，外装下見板貼のベランダ付洋館で，連子格子･上げ下げ･引違･回転と多様な開口部形式をとる。軒板飾，高欄に擬洋風建築の意匠を窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001912"},{"id":"00003989","register_sub_id":"101","register_pk":"104979","name":"旧今泉医院診療棟","kana":"きゅういまいずみいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市御津町御馬西37","lat":34.80809,"lng":137.314728,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積221㎡","structure_material":"木造平屋一部2階建","registered":"2004.03.02(平成16.03.02)","register_no":"23 － 0130","desc":"敷地西端に西面して建つ。正面は左右対称の洋風意匠で統一し，中央部のみ２階を設ける。前面中央には洋風の車寄せを張り出し，上部に病院名を記す額を掲げている。屋根は寄棟造，桟瓦葺で，外壁はドイツ壁とする。洋風意匠を導入した病院建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003989"},{"id":"00003991","register_sub_id":"101","register_pk":"104981","name":"旧今泉医院手洗い場","kana":"きゅういまいずみいいんてあらいば","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市御津町御馬西37","lat":34.80810189,"lng":137.3146331,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"コンクリート造、面積1.8㎡","structure_material":"コンクリート造","registered":"2004.03.02(平成16.03.02)","register_no":"23 － 0132","desc":"診療所前庭に位置する手洗い場。当時の農村地域の病院に良く設けられていたもので，患者が病院に入る前に使用していた。当初は井戸水を水源とし，診療所東側の高架水槽から配水していた。昭和初期の病院の在り方を，今日に伝える工作物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003991"},{"id":"00003990","register_sub_id":"101","register_pk":"104980","name":"旧今泉医院病室棟","kana":"きゅういまいずみいいんびょうしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊川市御津町御馬西37","lat":34.808216,"lng":137.31485,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"23 － 0131","desc":"診療棟の北東隅に接して建つ。切妻造，桟瓦葺で，西端に土間玄関を開く。内部は６畳の病室３室を配し，東の１室のみ床を備え，病室の南北には板縁を通す。診療棟と異なり和風意匠で統一し，平面も伝統的な構成に準ずる。病院建築の発展過程を示す建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003990"},{"id":"00010804","register_sub_id":"101","register_pk":"201639","name":"旧岡田医院給水塔","kana":"きゅうおかだいいんきゅうすいとう","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.966968,"lng":136.865183,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、高さ3.9m","structure_material":"鉄筋コンクリート造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0447","desc":"主屋北側中央に隣接している。鉄筋コンクリート造、高さ二・八メートルの柱四本を内転びに立て、平面が一・四×一・一メートル、高さ一・一メートルの貯水槽を支える。診療所と住居の一日分の井戸水を貯め、各所に供給した。近代の生活を物語る構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010804"},{"id":"00010802","register_sub_id":"101","register_pk":"201637","name":"旧岡田医院蔵","kana":"きゅうおかだいいんくら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.967126,"lng":136.865266,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0445","desc":"敷地北東部の入口に建つ。木造二階建、南北棟の切妻造桟瓦葺で、一階を下見板張、二階をドイツ壁風仕上げのモルタル塗とする。弓状の梁を用いた小屋で、隅を火打梁で固める。窓の鉄格子、小庇の装飾鋳物の持送り、漆喰塗の内壁など、丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010802"},{"id":"00010800","register_sub_id":"101","register_pk":"201635","name":"旧岡田医院主屋","kana":"きゅうおかだいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.966935,"lng":136.865252,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0443","desc":"敷地中央に位置し、南に築かれた庭園に面して建つ。東西に細長い木造二階建、入母屋造桟瓦葺で、小屋はトラス組である。軒を出桁造、ガラス戸を多用した開放的なつくりになる。中廊下式の一階平面、洋風応接室やサンルームを設ける点に時代的特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010800"},{"id":"00010801","register_sub_id":"101","register_pk":"201636","name":"旧岡田医院診療所棟","kana":"きゅうおかだいいんしんりょうじょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.967014,"lng":136.865389,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0444","desc":"主屋東に接続し、北面に主屋と併用の玄関を設ける。北半を二階建、南半を平屋建、寄棟造桟瓦葺とし、一階は診療室や処置室、二階は看護婦居室である。横溝彫付で煉瓦色の一階外壁やコーニスを廻した二階外壁など洋風意匠で、特色ある地域景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010801"},{"id":"00010803","register_sub_id":"101","register_pk":"201638","name":"旧岡田医院道具蔵","kana":"きゅうおかだいいんどうぐぐら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.966905,"lng":136.865069,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積42㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0446","desc":"木造二階建、南北棟の切妻造桟瓦葺で、東面に下屋庇を設け、小屋はトラス組とする。一階外壁は扉口のある東面がモルタル塗、南面と西面が下見板張、街路側北面が竪目地付モルタル塗、二階は石積風の疑似モルタル塗である。敷地の北西隅の構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010803"},{"id":"00010805","register_sub_id":"101","register_pk":"201640","name":"旧岡田医院塀","kana":"きゅうおかだいいんへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県知多市岡田字開戸24","lat":34.967053,"lng":136.865131,"geo_status":"db","era":"昭和4頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、総延長33m","structure_material":"鉄筋コンクリート造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0448","desc":"蔵から道具蔵の間に設けている。谷積風の石積基礎上に立上げた高さ約一・九メートルの鉄筋コンクリート造の塀で、約二・三メートル間隔に柱形を設け、その間をアーチ形の壁で連結し、ほぼ中間に非常用通路を設ける。敷地北辺の独特な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010805"},{"id":"00014615","register_sub_id":"101","register_pk":"515157","name":"旧常滑市立陶芸研究所（とこなめ陶の森陶芸研究所）正門","kana":"きゅうとこなめしりつとうげいけんきゅうじょ（とこなめとうのもりとうげいけんきゅうじょ）せいもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県常滑市奥条七丁目22","lat":34.88651111,"lng":136.85036944,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"コンクリートブロック造、間口5.0m、延長11m","structure_material":"コンクリートブロック造","registered":"2023.08.07(令和5.08.07)","register_no":"23 - 0588","desc":"本館同様、堀口捨己の設計にかかる陶芸研究所の正門。鉄格子戸を左右にスライドさせる間口五メートルの門扉と、門扉から矩折に控えた左右対称のコンクリートブロック塀からなる。門扉上部の板に打抜かれた極太明朝体の「常滑陶芸研究所」の文字が力強い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014615"},{"id":"00014614","register_sub_id":"101","register_pk":"515156","name":"旧常滑市立陶芸研究所（とこなめ陶の森陶芸研究所）本館","kana":"きゅうとこなめしりつとうげいけんきゅうじょ（とこなめとうのもりとうげいけんきゅうじょ）ほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県常滑市奥条七丁目22","lat":34.88685833,"lng":136.85054722,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、建築面積203㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2023.08.07(令和5.08.07)","register_no":"23 - 0587","desc":"堀口捨己設計の陶芸研究所。鉄筋コンクリート造２階建で、紫タイル貼の外壁にバルコニーや庇を張出して水平性を強調。内部は階段ホール西にトップライト付の展示室、東に事務室や会議室等。赤と金を配す応接室や銀の展示室等、色使い含め設計者の個性が光る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014614"},{"id":"00015464","register_sub_id":"101","register_pk":"533479","name":"創垂館","kana":"そうすいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県小牧市堀の内一丁目2","lat":35.29125,"lng":136.91384722,"geo_status":"db","era":"明治21年／昭和24年移築、令和4年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0616","desc":"史跡小牧山の中腹にある尾張徳川家の旧迎賓施設。南面して建つ寄棟造桟瓦葺で南面西寄りに式台玄関を付す。西を土間の供待所と勝手、東を続き間座敷とし、東・南に入側の広縁と竹の濡縁を廻らし庭を望む。広い式台など格式を備え、良材を用いた上質な座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015464"},{"id":"00010160","register_sub_id":"101","register_pk":"197993","name":"蘇山荘","kana":"そざんそう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1001","lat":35.184286,"lng":136.932195,"geo_status":"db","era":"昭和12／昭和12移築・平成16改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0408","desc":"木曽材の宣伝を目的に名古屋汎太平洋平和博覧会の迎賓館和館として建設され、閉会後に移築された。車寄付玄関の南側に八畳、北側に台所等を配し、西奥に客間三室を配する。ヒノキやサワラ等、木曽の良材をふんだんに利用し見応えがあり、室内意匠を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010160"},{"id":"00000212","register_sub_id":"101","register_pk":"101202","name":"徳川美術館本館","kana":"とくがわびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.18353273,"lng":136.93320313,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上1階地下1階建，瓦葺，建築面積506㎡","structure_material":"鉄骨鉄筋コンクリート造地上1階地下1階建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0003","desc":"設計競技の１等案をもとに吉本与志雄が実施設計を行った。施工は竹中工務店。外観の意匠は城壁を思わす外壁を巡らし、屋根は緑色釉薬瓦葺とし鯱を置く。全体としていわゆる帝冠様式のデザインをもつ建物で、尾張徳川家の所蔵品を展示する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000212"},{"id":"00000213","register_sub_id":"101","register_pk":"101203","name":"徳川美術館南収蔵庫","kana":"とくがわびじゅつかんみなみしゅうぞうこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区徳川町1017","lat":35.18354247,"lng":136.93357388,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建，瓦葺，建築面積250㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"23 － 0004","desc":"本館とともに吉本与志雄が実施設計を行った。施工は竹中工務店。本館の西側に位置する中規模の鉄筋コンクリート造階建の収蔵庫。切妻造、本瓦葺で、開口部がほとんど無い大壁造風の建物である。本館に接続しともに重厚な外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000213"},{"id":"00000792","register_sub_id":"101","register_pk":"101782","name":"豊橋市公会堂","kana":"とよはししこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通2-22","lat":34.76804673,"lng":137.39222025,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造３階建，建築面積1202㎡","structure_material":"鉄筋コンクリート造３階建","registered":"1998.09.02(平成10.09.02)","register_no":"23 － 0015","desc":"市制２５周年の記念建造物に相応しく，大階段・コリント式列柱による玄関ロッジア・両脇の階段室が堂々たる正面ファサードをつくる。階段室の半球ドームと四方に配置された羽ばたく大鷲がシンボル。静岡や浜松の公会堂を手がけた中村與資平の設計になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000792"},{"id":"00011710","register_sub_id":"101","register_pk":"210726","name":"中村公園記念館","kana":"なかむらこうえんきねんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市中村区中村町字高畑","lat":35.17479,"lng":136.854221,"geo_status":"db","era":"明治43年／大正期・昭和25年頃・同33年・同45年・同50年・平成28年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"23-0480","desc":"迎賓館として建てられたもので、Ｌ字型平面の木造平屋建。正面中央に唐破風造の車寄を張り出し、四周に下屋を廻らす。西側は和室三室を並べ、吟味された良材を用い、座敷飾りを備え、天井高の高い空間と共に、迎賓館としての風格を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011710"},{"id":"00013401","register_sub_id":"101","register_pk":"368486","name":"名古屋市公会堂","kana":"なごやしこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞一丁目101","lat":35.15677778,"lng":136.91911944,"geo_status":"db","era":"昭和5年／昭和33年・同55年・平成31年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上4階地下1階建、建築面積2765㎡","structure_material":"鉄骨鉄筋コンクリート造地上4階地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"23 － 0548","desc":"名古屋市鶴舞公園内に位置し、昭和天皇御成婚記念事業で建てた。外観は茶系の落ち着いた色調で整え、最上階の円形アーチ窓や隅部の丸み等、ロマネスク的表現とする。内部は、三層吹抜の大ホールを中心に各室を配す。初期の鉄骨鉄筋コンクリート造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013401"},{"id":"00006337","register_sub_id":"101","register_pk":"107320","name":"名古屋大学医学部附属病院門及び外塀（旧愛知県立愛知病院正門及び外塀）","kana":"なごやだいがくいがくぶふぞくびょういんもんおよびそとべい（きゅうあいちけんりつあいちびょういんせいもんおよびそとべい）","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞町65","lat":35.15711211,"lng":136.92098502,"geo_status":"db","era":"大正3／昭和5・平成11改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門 石造門柱2基、間口4.2m、塀 煉瓦造、総延長16m","structure_material":"門 石造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0247","desc":"名古屋大学鶴舞キャンパス敷地の南辺にあり、道路を挟んで鶴舞公園に面する。門柱は花崗岩の方柱で、新築病棟の柱にそのデザインが引用されている。塀は昭和５年にスクラッチタイルとテラコッタで改修したもので、当時のデザイン傾向が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006337"},{"id":"00006373","register_sub_id":"101","register_pk":"107356","name":"名古屋大学医学部附属病院門及び外塀（旧愛知県立愛知病院通用門及び外塀）","kana":"なごやだいがくいがくぶふぞくびょういんもんおよびそとべい（きゅうあいちけんりつあいちびょういんつうようもんおよびそとべい）","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市昭和区鶴舞町65","lat":35.15666517,"lng":136.92224554,"geo_status":"db","era":"大正後期／昭和5改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 石造門柱2基、間口7.4m、塀 煉瓦造、総延長55m","structure_material":"門 石造門柱2基","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0248","desc":"名古屋大学鶴舞キャンパス敷地の南東にある。門柱、塀とも煉瓦造で昭和５年にスクラッチタイルとテラコッタで改修された。タイルは釉薬が施され、高いデザイン感覚とともに材料品質もよい。テラコッタ装飾は立体的かつ幾何学的な意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006373"},{"id":"00001113","register_sub_id":"101","register_pk":"102103","name":"西尾市岩瀬文庫書庫","kana":"にしおしいわせぶんこしょこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県西尾市亀沢町474","lat":34.87442045,"lng":137.05347681,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造地下１階地上３階建，瓦葺，建築面積80㎡","structure_material":"煉瓦造地下１階地上３階建","registered":"1999.06.07(平成11.06.07)","register_no":"23 － 0022","desc":"地元出身の豪商岩瀬弥助が，収集した蔵書を市民に閲覧できるようにつくった文庫の書庫として建てられた。煉瓦の外壁を基調に窓の上部や窓台等にアクセントとして石材を用いた外観はよく整っている。内部は木組みで柱を立て３層に床を張り蔵書を納めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001113"},{"id":"00001114","register_sub_id":"101","register_pk":"102104","name":"西尾市立図書館おもちゃ館（旧岩瀬文庫児童館）","kana":"にしおしりつとしょかんおもちゃかん（きゅういわせぶんこじどうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県西尾市亀沢町474","lat":34.87390794,"lng":137.05341439,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積57㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"23 － 0023","desc":"岩瀬文庫の児童館として建てられた。木造平屋建の小規模な洋風建築で，下見板貼りの外壁，ハーフティンバー風の妻飾，縦長の上下窓等に特徴がある。児童用の施設にふさわしいデザインで，現在も児童用の施設として使われている点にもみどころがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001114"},{"id":"00002045","register_sub_id":"101","register_pk":"103035","name":"羽田八幡宮蔵（旧羽田八幡宮文庫）","kana":"はだはちまんぐうくら（きゅうはだはちまんぐうぶんこ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市花田町字斉藤56-3","lat":34.76497066,"lng":137.37653386,"geo_status":"db","era":"嘉永1","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"23 － 0051","desc":"近代的図書館の先駆とされる羽田八幡宮文庫の書庫。桁行３間，梁行２間の規模，切妻造，桟瓦葺，平入の標準的なつくりの平屋建土蔵で，書庫らしく南面に小さな窓を設けただけの閉鎖的な構えをとり，東面に１間幅の戸口を設けて社務所離れに繋げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002045"},{"id":"00002046","register_sub_id":"101","register_pk":"103036","name":"羽田八幡宮門（旧羽田八幡宮文庫正門）","kana":"はだはちまんぐうもん（きゅうはだはちまんぐうぶんこせいもん）","category":"文化福祉","subcategory":"その他工作物","type_guess":"博物館","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市花田町字斉藤58","lat":34.76477096,"lng":137.37653314,"geo_status":"db","era":"嘉永1","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造、瓦葺、間口3m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"23 － 0052","desc":"豊橋駅西口近く，北西方に位置する羽田八幡宮の参道中程に西面して建つ。正面全幅１０尺ほどで中央１間分を通路とし，両側２尺づつは腰を板張とした土壁とする。桟瓦葺の切妻屋根を架けた簡素な腕木門であるが，由緒ある文庫位置の目印として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002046"},{"id":"00006767","register_sub_id":"101","register_pk":"107749","name":"三谷町北区山車蔵","kana":"みやちょうきたくやまぐら","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県蒲郡市三谷町七舗153-1他","lat":34.815315,"lng":137.24561372,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積35㎡","structure_material":"煉瓦造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0254","desc":"通りに西面して敷地を占め、前面に引き回しの場を設ける。煉瓦造で、桁行・梁間とも５．９ｍの規模で、切妻造桟瓦葺とする。山車を収蔵するため、開口部はアーチ頂部まで６ｍ高に及び、銅板張の両開戸をたてる。煉瓦造の山車蔵という数少ない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006767"},{"id":"00003666","register_sub_id":"101","register_pk":"104656","name":"明治村北里研究所本館","kana":"めいじむらきたざとけんきゅうじょほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34156,"lng":136.991684,"geo_status":"db","era":"大正4／昭和55移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、スレート葺一部銅板葺、建築面積360㎡、塔屋付","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0079","desc":"木造２階建の洋風建築。天然スレート葺の腰折れ屋根に櫛形の屋根窓を置く。玄関上には段状破風と八角小塔を飾る。外壁は下見板張で，腰壁と軒下小壁を竪羽目板張とし，上げ下げ窓まわりに柱形を表す。玄関車寄は縦溝付の角柱で支え，パラペットを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003666"},{"id":"00003662","register_sub_id":"101","register_pk":"104652","name":"明治村清水医院","kana":"めいじむらしみずいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34177783,"lng":136.98897136,"geo_status":"db","era":"明治30代／昭和48移築","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、柿葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0075","desc":"土蔵造２階建，切妻造，平入で木曽檜のこけら葺とする。隅に柱型を付け，外壁の漆喰に目地を切って石造風に見せるなど洋風を意識した意匠をもつ。開口部は櫛形アーチだが，窓は引込み戸である。１階は通り土間式平面，２階は数寄屋風座敷と内部は和風である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003662"},{"id":"00003858","register_sub_id":"101","register_pk":"104848","name":"明治村日本赤十字社中央病院病棟","kana":"めいじむらにほんせきじゅうじしゃちゅうおうびょういんびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34304926,"lng":136.99102585,"geo_status":"db","era":"明治23／昭和49移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0092","desc":"木造平屋建，寄棟造，桟瓦葺で，棟に換気塔を置く。煉瓦造の高い基礎に建ち，廊下を高床に造る。外壁はドイツ下見で，ハーフティンバー風に柱形をつける。病室は欄間付の上げ下げ窓に両開鎧戸，廊下は引違ガラス窓で小壁に革紐装飾を施す。設計は片山東熊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003858"},{"id":"00003859","register_sub_id":"101","register_pk":"104849","name":"明治村日本赤十字社中央病院付属便所","kana":"めいじむらにほんせきじゅうじしゃちゅうおうびょういんふぞくべんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.3430597,"lng":136.99121322,"geo_status":"db","era":"明治23／昭和49移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0093","desc":"木造平屋建，寄棟造，桟瓦葺で棟上に切妻屋根の換気塔を載せる。切石基礎上に建ち，外壁はドイツ下見で，ハーフティンバー風に柱形で飾り，小壁に山形模様を刻む。妻側に上げ下げ窓，平側に引違窓を開く。設計は片山東熊。小規模だが細部まで意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003859"},{"id":"00001275","register_sub_id":"101","register_pk":"102265","name":"車山蔵","kana":"やまぐら","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券779","lat":35.38399831,"lng":136.93963283,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積37㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"23 － 0033","desc":"犬山祭りの際にくりだす山車の格納蔵。間口４．５５ｍ、桁行８．２２ｍ規模の木造平屋建、瓦葺切妻屋根、妻入の建屋で、桁高は７ｍある。棟梁は犬山藩御用大工の系譜を継ぐ市橋清次郎で、水平筋違や側壁の筋違などに洋風建築技術の導入が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001275"},{"id":"00005079","register_sub_id":"101","register_pk":"106069","name":"龍影閣（旧名古屋博物館品評所）","kana":"りょうえいかく（きゅうなごやはくぶつかんひんぴょうじょ）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市熱田区神宮1-1-1","lat":35.125832,"lng":136.90802,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造2階建、瓦葺、建築面積295㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"23 － 0055","desc":"博覧会場の品評所として建設。木造２階建，寄棟造の和風建築で，階下に１８畳と１６畳半の座敷，階上に１０畳と上段付８畳（明治天皇御座所）を配置し，四周に廊下を巡らし，奥に階段室を設ける。棟梁は鈴木幸右衛門で，初期博覧会施設の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005079"},{"id":"00009021","register_sub_id":"101","register_pk":"162381","name":"石薬師文庫閲覧所","kana":"いしやくしぶんこえつらんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県鈴鹿市石薬師町字中町1707-3","lat":34.90356659,"lng":136.54766596,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0111","desc":"佐佐木信綱生家土蔵の東、旧東海道沿いに建つ。Ｌ字形棟の切妻造スレート葺で、入隅に下屋を設け、玄関とする。建築面積２９㎡。玄関奥を前室とし、その南に閲覧室を配する。クリーム色のモルタル外壁に大きく窓を穿ち、明るい内部空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009021"},{"id":"00014247","register_sub_id":"101","register_pk":"509637","name":"旧小渕医院診療棟","kana":"きゅうこぶちいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市一志町波瀬1969","lat":34.62723056,"lng":136.39236667,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0314","desc":"津市南西の農村に位置。平屋建寄棟造桟瓦葺。東正面に角柱で陸屋根の玄関ポーチを付け両脇に矩形窓を開ける。内部は玄関奥を待合室、脇に受付調剤室と診療室を配する。奥は中廊下両脇に内玄関や応接室、事務所を配す。洋風医院の典型で農村の小集落に希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014247"},{"id":"00014250","register_sub_id":"101","register_pk":"509640","name":"旧吉田医院主屋","kana":"きゅうよしだいいんおもや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市白塚町字南新畑4998-2","lat":34.75774722,"lng":136.52741667,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積225㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0317","desc":"伊勢湾西岸の漁村に所在する医院。桟瓦葺の玄関棟、診療棟、居住棟で構成。診療棟は平屋建半切妻造。下見板張の上部をドイツ壁とし矩形窓を並べ、内部は診療室やレントゲン室を配す。居住棟は二階建入母屋造で各階とも田の字形で四室とる。洋風医院の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014250"},{"id":"00014251","register_sub_id":"101","register_pk":"509641","name":"旧吉田医院入院棟","kana":"きゅうよしだいいんにゅういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県津市白塚町字南新畑4998-2","lat":34.75764444,"lng":136.52753889,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0318","desc":"敷地の奥に位置し主屋と廊下で接続する。南北棟の平屋建寄棟造桟瓦葺で外壁は下見板張。内部は片廊下平面で入院室三室と、北端にお手伝い室を配する。入院室は引違ガラス戸の窓と押入を備える簡素なつくり。歴史的景観を構成する地域医院の要素として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014251"},{"id":"00014252","register_sub_id":"101","register_pk":"509642","name":"旧吉田医院門","kana":"きゅうよしだいいんもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市白塚町字南新畑4998-2","lat":34.75780833,"lng":136.52731389,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"石造、間口2.1m","structure_material":"石造","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0319","desc":"旧道に面して立つ医院正門。間口二・一メートル、高さ二・四メートルの一対の石柱を構え、間に鉄製アーチを架ける。石柱は江戸切仕上で柱頭を扁平な四角錐とし、アーチは渦巻き飾りを付けて中央に突針を立てる。洋風医院の表構えとして通り沿いの景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014252"},{"id":"00003103","register_sub_id":"101","register_pk":"104093","name":"旧四日市市立図書館","kana":"きゅうよっかいちしりつとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県四日市市諏訪栄町22-25諏訪公園内","lat":34.96865125,"lng":136.62196258,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積197㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"24 － 0046","desc":"地元の実業家熊沢一衛が四日市市に寄付した図書館で，設計は清水組の小笹徳蔵。鉄筋コンクリート造２階建，外観はスクラッチタイル張で比較的窓を大きく取る。繁華街に隣接した場所にあり，現在はこどもの家（児童館）として市民に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003103"},{"id":"00007054","register_sub_id":"101","register_pk":"108036","name":"蔵前祭車庫","kana":"くらまえさいしゃこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県桑名市船馬町7","lat":35.068939,"lng":136.692627,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積34㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"24 － 0072","desc":"河岸屈曲部の橋の袂に建つ。建築面積３４㎡、鉄筋コンクリート造平屋建切妻造、鉄板瓦棒葺。妻面両端にパラペットを立ち上げ、外壁は柱型とスタッコ塗壁で構成し、小屋はハウトラスを組む。県内における初期の鉄筋コンクリート造建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007054"},{"id":"00000830","register_sub_id":"101","register_pk":"101820","name":"神宮徴古館","kana":"じんぐうちょうこかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市神田久志本町1754-1","lat":34.48582886,"lng":136.7248766,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"煉瓦造平屋建，銅板葺，建築面積1611㎡","structure_material":"煉瓦造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"24 － 0020","desc":"神宮の歴史資料を収集展示する目的で建てられた。設計は片山東熊・高山幸次郎で，煉瓦造に石貼仕上げとする端正な意匠の建物。平面は，中央ホ－ルとその奥の貴賓室，左右の翼屋を廊で繋ぐ構成になる。戦災後大改修されたが，外壁廻りは保存されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000830"},{"id":"00000831","register_sub_id":"101","register_pk":"101821","name":"神宮農業館","kana":"じんぐうのうぎょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市神田久志本町1754-1","lat":34.48679945,"lng":136.7243766,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積439㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"24 － 0021","desc":"農業の啓発と発展を目的として建てた施設。元はロの字型の平面であったが，近年の移築で中央部の宝形屋根の望楼の左右に翼屋を配し廊で繋ぐ前半部のみに縮小された。外観は和風で，内部架構は洋風にまとめる優れた技量がうかがえる。設計は片山東熊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000831"},{"id":"00009776","register_sub_id":"101","register_pk":"195605","name":"神武参剣道場","kana":"じんむさんけんどうじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県志摩市磯部町上之郷字上ノ里375-1他","lat":34.38015859,"lng":136.81030373,"geo_status":"db","era":"昭和36","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造2階建、瓦葺、建築面積248㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0161","desc":"伊雑宮向かいの敷地に西面して建つ。木造二階建、入母屋造桟瓦葺で、一階周囲を下屋とし、正面中央に入母屋造の玄関を構える。柱上に舟肘木を載せ、壁は真壁漆喰塗で、腰を竪板張とする。内部は一階が祭壇付道場、二階は広間とする。風格ある外観をもつ武道場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009776"},{"id":"00005977","register_sub_id":"101","register_pk":"106962","name":"鈴屋遺蹟保存会旧事務所","kana":"すずのやいせきほぞんかいきゅうじむしょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.57659024,"lng":136.52586038,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0063","desc":"松阪城隠居丸跡南東に位置し，南東に面して建つ。桁行７間，梁間４間の規模で，木造平屋建，入母屋造，桟瓦葺。正面中央に銅板葺唐破風屋根の玄関を構え，奥に玄関ホール，南西端に洋間閲覧室，北西に座敷１０畳間を配す。近代和風の事務所建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005977"},{"id":"00005979","register_sub_id":"101","register_pk":"106964","name":"鈴屋遺蹟保存会正門","kana":"すずのやいせきほぞんかいせいもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.57538769,"lng":136.52619265,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右潜戸付","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0065","desc":"旧事務所南東に位置し，敷地北東正面に建つ。一間一戸の四脚門の形式をとり，屋根を切妻造，本瓦葺とする。左右に潜戸を付ける。柱を貫通した梁の頭を大仏様木鼻とし，梁中央に板蟇股を載せ，腕木の下を柱及び斗で支えるなど，特徴ある意匠と構造を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005979"},{"id":"00005978","register_sub_id":"101","register_pk":"106963","name":"鈴屋遺蹟保存会倉庫","kana":"すずのやいせきほぞんかいそうこ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.575397,"lng":136.52597,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡、渡廊下付","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0064","desc":"旧事務所の南西に北東に面して建つ。桁行３間，梁間２間の規模で，土蔵造２階建，寄棟造，桟瓦葺とし，正面に瓦葺の土庇をかけ，渡廊下で旧事務所と連絡する。基礎を煉瓦積，外壁を漆喰塗とし，外側を下見板で養生する。軒を深く出さずに落ち着いた外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005978"},{"id":"00005980","register_sub_id":"101","register_pk":"106965","name":"鈴屋遺蹟保存会塀","kana":"すずのやいせきほぞんかいへい","category":"文化福祉","subcategory":"その他工作物","type_guess":"門・塀","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1537","lat":34.57534043,"lng":136.52599191,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、瓦葺、総延長11m","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"24 － 0066","desc":"旧事務所南西面から南西に本居宣長の旧宅まで延び，延長１１ｍで柱間を９間とする。正面の広場からの目隠しとなる。旧宅側の１間に出入口を設ける。木造で，腰を下見板張とし，上方に連子を嵌め，柱から腕木を出して瓦屋根を支え，重厚な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005980"},{"id":"00010826","register_sub_id":"101","register_pk":"201661","name":"中井家住宅主屋","kana":"なかいけじゅうたくしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県名張市元町452","lat":34.620326,"lng":136.086943,"geo_status":"db","era":"昭和7／昭和40改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積124㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0227","desc":"市街地の角地に建つ、もと耳鼻咽喉科の医院建築で、木造二階建である。下見板張を基調とする外観は、上下階に並べた窓枠を縦に繋ぐ額縁で垂直線を強調し、上下の窓間を三分割して菱模様を飾るなど、幾何意匠でまとめる。街路のランドマークとなる洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010826"},{"id":"00000293","register_sub_id":"101","register_pk":"101283","name":"松阪市立歴史民俗資料館（旧飯南郡図書館）倉庫","kana":"まつさかしりつれきしみんぞくしりょうかん（きゅういいなんぐんとしょかん）そうこ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1539","lat":34.57668316,"lng":136.52600906,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積20㎡","structure_material":"土蔵造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"24 － 0010","desc":"本館の東に隣接して建つ本館と同時に建設された２階建の土蔵。漆喰壁を下見板で覆い，外観の意匠を本館とあわせるが，高さを低く押さえている点は立ちの高い本館とは対照的である。市民の寄付でつくられた図書館の付属施設として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000293"},{"id":"00000292","register_sub_id":"101","register_pk":"101282","name":"松阪市立歴史民俗資料館（旧飯南郡図書館）本館","kana":"まつさかしりつれきしみんぞくしりょうかん（きゅういいなんぐんとしょかん）ほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市殿町1539","lat":34.57659024,"lng":136.52586038,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建，瓦葺，建築面積239㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"24 － 0009","desc":"松阪城跡公園の北端に建つ。木造，２階建で伝統的な和風の意匠をもち，左右に翼部，中央に玄関が突出した左右対称の構成に特徴がある。設計は清水義一である。近代における伝統的な和風建築の展開を知ることができる好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000292"},{"id":"00007053","register_sub_id":"101","register_pk":"108035","name":"楽翁公百年祭記念宝物館","kana":"らくおうこうひゃくねんさいきねんほうもつかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県桑名市吉之丸9","lat":35.065273,"lng":136.69838,"geo_status":"db","era":"昭和9／昭和33改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積86㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"24 － 0071","desc":"神社境内の一隅に建つ。松平定信（楽翁）を顕彰する記念宝物館。建築面積８６㎡、鉄筋コンクリート造２階建。寄棟造桟瓦葺、正面に切妻破風を飾る。外壁は洗出し仕上げで、１階を石積風とし、２階は柱や長押型を表現するなど、和風意匠を加味する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007053"},{"id":"00007752","register_sub_id":"101","register_pk":"108733","name":"アンドリュース記念館（旧近江八幡ＹＭＣＡ会館）","kana":"あんどりゅーすきねんかん（きゅうおうみはちまんわいえむしーえーかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市為心町中31","lat":35.13795563,"lng":136.09222125,"geo_status":"db","era":"昭和10／平成19改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積161㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"25-0277","desc":"八幡山東南の市街地に位置する。桁行１５ｍ梁間１１ｍの木造２階建、南北棟の入母屋造桟瓦葺。２階は南寄りに和室二室、北に洋室二室を並べ、中央を階段室等とする。釉薬瓦の赤とモルタル仕上げ壁の白が好対照をなし、親しみのある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007752"},{"id":"00008132","register_sub_id":"101","register_pk":"132530","name":"石田家住宅洋館（石田歯科医院）","kana":"いしだけいしだけじゅうたくようかん（いしだしかいいん）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市中央1-409他","lat":35.00956718,"lng":135.86462812,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"25 － 0283","desc":"浜通りに北面する洋館。東西棟の切妻造で、深緑色のスパニッシュ瓦を葺く。２階は中央に小さなバルコニーを設け、上部にタイルを縁取った丸い文様を飾り、切妻屋根を掛ける。外壁はグレーのリシン仕上げで、窓枠を薄桃色に塗る。伝統的な町並に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008132"},{"id":"00010179","register_sub_id":"101","register_pk":"198012","name":"ヴォーリズ記念病院旧本館（ツッカーハウス）","kana":"ゔぉーりずきねんびょういんきゅうほんかん（つっかーはうす）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市北之庄町492","lat":35.152028,"lng":136.089106,"geo_status":"db","era":"大正7／昭和9改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積354㎡","structure_material":"木造2階一部3階建","registered":"2014.10.07(平成26.10.07)","register_no":"25 － 0348","desc":"中央の切妻造三階建の左右にのばす翼部両端を半八角形平面とする。玄関ポーチを半円アーチで構成し上部にベイウィンドウを開く。内部意匠にもヴォーリズの作風を示し、病室のおかれた二階開口を広めて通風採光に配慮するなど、結核病棟としての特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010179"},{"id":"00000980","register_sub_id":"101","register_pk":"101970","name":"近江八幡ユース・ホステル（旧蒲生郡勧業館）","kana":"おうみはちまんゆーす・ほすてる（きゅうがもうぐんかんぎょうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市円山町610","lat":35.16495665,"lng":136.08825157,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造２階建，瓦葺，建築面積329㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"25 － 0103","desc":"明治中期以降流行しだす総二階木造和風の公共建築。真壁造で，腰を竪羽目とし，連続窓により立面をつくる。瓦葺入母屋の大屋根を架け，正面中央に唐破風の玄関を付ける。虹梁・笈形付大瓶束の玄関妻飾や内部の大階段などの凝った造りが見所となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000980"},{"id":"00008498","register_sub_id":"101","register_pk":"134894","name":"大津市旧大津公会堂","kana":"おおつしきゅうおおつこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市浜大津1-72-1","lat":35.01045707,"lng":135.86536471,"geo_status":"db","era":"昭和9年／昭和21年・昭和60年・昭和63年・平成22年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積430㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2011.01.26(平成23.01.26)","register_no":"25 － 0293","desc":"大津市の中心市街地に建つ。東西一七メートル南北二八メートルで、東面に車寄せを突き出す。鉄筋コンクリート造三階地下一階建、外壁スクラッチタイル貼。左右対称で、三階に半円アーチ窓、隅に円窓、一・二階に縦長窓を開け、格調ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008498"},{"id":"00011976","register_sub_id":"101","register_pk":"211111","name":"旧近江療養院希望館（五葉館）","kana":"きゅうおうみりょうよういんきぼうかん（ごようかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市北之庄町字川西492","lat":35.15228,"lng":136.088525,"geo_status":"db","era":"大正7年／平成27年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"25-400","desc":"旧本館北側の斜面に建つ病棟。中央ラウンジの北を入口とし、南側に病室五室を放射状に配し、各病室の三面に窓を開いて通風と採光を確保する。外壁はドイツ壁で、窓に鎧戸をたて、ラウンジの屋根頂部に換気塔を載せる。独創的な形態をもつ個室型の結核療養施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011976"},{"id":"00014036","register_sub_id":"101","register_pk":"508296","name":"旧北村医院（李軒邸）井戸屋形","kana":"きゅうきたむらいいん（りけんてい）いどやかた","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町字辻下761-1","lat":35.37486389,"lng":136.32827222,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0486","desc":"敷地南側、表門の内側東に建つ井戸屋形。切妻造桟瓦葺、軒は疎垂木小舞打。軸部は開放で洗い場入口を除き飛貫を入れる。正面両端柱に控柱を添える。南半に井戸、北半を洗い場とする。井戸上の化粧棟木下端には吊り金具が残る。医師宅の建物構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014036"},{"id":"00014037","register_sub_id":"101","register_pk":"508297","name":"旧北村医院（李軒邸）表門","kana":"きゅうきたむらいいん（りけんてい）おもてもん","category":"文化福祉","subcategory":"その他工作物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町字辻下761-1","lat":35.37485278,"lng":136.32827222,"geo_status":"db","era":"元治2年(1865)","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、瓦葺、間口2.6m","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0487","desc":"敷地南側に離れ座敷の東に接続して建つ薬医門。切妻造桟瓦葺。両脇に袖塀を設け、西側に潜戸を付す。桁行に比して梁間が大きい。袖壁は土壁で腰を竪板張。梁の木鼻に繰形を施す。扉は板唐戸で八双金具等を付ける。医師宅の表構えに相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014037"},{"id":"00014029","register_sub_id":"101","register_pk":"508289","name":"旧北村医院（李軒邸）主屋","kana":"きゅうきたむらいいん（りけんてい）おもや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.374975,"lng":136.32814444,"geo_status":"db","era":"文政10年(1827)","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0479","desc":"長浜市街から東方の農村集落に南面して建つ医院建築。二階建切妻造桟瓦葺、正面中央に処置室を張出し診察棟と接続。東側に土間を配し、居室部は六間取平面で表側を医院とする。西端二間を書院座敷とし文人の書画で飾る。近世から続く医家の主屋として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014029"},{"id":"00014038","register_sub_id":"101","register_pk":"508298","name":"旧北村医院（李軒邸）車庫","kana":"きゅうきたむらいいん（りけんてい）しゃこ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37478333,"lng":136.32820833,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0488","desc":"離れ座敷の南にあり、東面する車庫。平屋建、正面入母屋背面切妻造桟瓦葺。妻飾りは木連格子、正面は襷桟付ガラス欄間を入れ、出入口を開放とするがもとは双折戸が入っていた。南面にガラス窓、北・西面に引違戸を設ける。医師宅に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014038"},{"id":"00014030","register_sub_id":"101","register_pk":"508290","name":"旧北村医院（李軒邸）診療棟","kana":"きゅうきたむらいいん（りけんてい）しんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37486667,"lng":136.32815556,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0480","desc":"医院主屋南面から待合棟北面に接続する南北棟の診療棟。平屋建、入母屋造桟瓦葺で、壁は漆喰仕上で腰を洗出仕上。内部は診察室と薬局の二室で、受付カウンター・視線を遮る摺りガラス等に診療機能がみえる。近世主屋と共に医院建築の変遷を物語る近代診療棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014030"},{"id":"00014035","register_sub_id":"101","register_pk":"508295","name":"旧北村医院（李軒邸）土蔵","kana":"きゅうきたむらいいん（りけんてい）どぞう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37505556,"lng":136.328025,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0485","desc":"通りに面した敷地北西隅に建ち、主屋の縁と接続する土蔵。土蔵造二階建、切妻造桟瓦葺で置屋根の梁先に絵様繰形を施す。外壁は漆喰仕上で一階を竪板張とする。正面扉は観音開き鋼製扉を備え、一階北面に板葺庇付の窓を設ける。医師宅に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014035"},{"id":"00014032","register_sub_id":"101","register_pk":"508292","name":"旧北村医院（李軒邸）西病棟","kana":"きゅうきたむらいいん（りけんてい）にしびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37507778,"lng":136.32815,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0482","desc":"主屋の北側、裏門の西に接続して建つ病棟。二階建、切妻造桟瓦葺で東面に下屋を付し物入・便所とする。南面東端を入口及び階段とし、各階とも東西に六畳間を二室並べ南北面に窓を配す。二階は起り天井で釣床を備える。明治の医家の様相を伝える希少な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014032"},{"id":"00014031","register_sub_id":"101","register_pk":"508291","name":"旧北村医院（李軒邸）離れ座敷（待合棟）","kana":"きゅうきたむらいいん（りけんてい）はなれざしき（まちあいとう）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37483611,"lng":136.32816667,"geo_status":"db","era":"慶応4年(1868)／大正後期改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0481","desc":"表門西隣で、診療棟南面に廊下で接続する和風医院建築。平屋建、寄棟造桟瓦葺。北面東端に入母屋造銅板葺の玄関庇を付す。中央に五畳半の待合、西に四畳半の書院座敷を並べる。面皮床柱や丸窓の意匠が座敷を印象付ける。当初隠居屋で医院建築の変遷を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014031"},{"id":"00014033","register_sub_id":"101","register_pk":"508293","name":"旧北村医院（李軒邸）東病棟","kana":"きゅうきたむらいいん（りけんてい）ひがしびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町761","lat":35.37507778,"lng":136.32835833,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0483","desc":"敷地北東部に建つ南北棟の病棟。二階建、切妻造桟瓦葺で西・北面に庇を廻す。外壁は真壁造に竪板張。西面南端に入口とし、内部幅一間を土間とする。各階とも一〇畳間で北面を押入とし二階南西隅に便所を設ける。木部は弁柄塗。地域医療の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014033"},{"id":"00014034","register_sub_id":"101","register_pk":"508294","name":"旧北村医院（李軒邸）東病棟便所","kana":"きゅうきたむらいいん（りけんてい）ひがしびょうとうべんじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市鳥羽上町字辻下761-1","lat":35.375025,"lng":136.32831111,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積4.2㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0484","desc":"東病棟の西側に建つ東西棟の便所。平屋建、切妻造桟瓦葺、壁は真壁造。正面は繰形付腕木で出桁とする。中央踏込み部の両側に個室を並べる。個室の床は赤色市松模様のタイル張。東個室は弁柄塗棹縁天井、西個室は漆喰塗込天井。医師宅に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014034"},{"id":"00013132","register_sub_id":"101","register_pk":"368288","name":"旧常喜医院馬小屋","kana":"きゅうじょうきいいんうまごや","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34733889,"lng":136.35439167,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0446","desc":"敷地南面に開く門の近く、敷地の南東に西面して建つ。木造平屋建、切妻造桟瓦葺平入で、西面の桁行三間のうち中央一間を片引戸の出入口とする。出入口は馬に配慮してか、吊戸とし敷居は設けず、内法高も高い。長年地域医療に従事してきた医家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013132"},{"id":"00013128","register_sub_id":"101","register_pk":"368284","name":"旧常喜医院主屋","kana":"きゅうじょうきいいんしゅおく","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.347525,"lng":136.35417778,"geo_status":"db","era":"明治37年／大正14年頃・昭和5年頃増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0442","desc":"米原市南部の農村集落にある代々医者を務めた旧家の主屋で、敷地中央に南面して建つ。一階南側に張出した玄関回りに医院機能をまとめ、北側と二階を住居とする。数次に渡る改修の図面が残り履歴がわかる。地域医療を担い続けた医家の建築の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013128"},{"id":"00013129","register_sub_id":"101","register_pk":"368285","name":"旧常喜医院書院","kana":"きゅうじょうきいいんしょいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34744167,"lng":136.35401389,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0443","desc":"主屋の西側に建ち、北側の廊下を介して主屋と繋ぐ。入母屋造桟瓦葺の周囲に下屋を廻らし、南面と東面の下屋は畳廊下とする。南側に接客用の書院之間、北側に次之間と八畳間を並べ、次之間の北西隅に三畳の化粧室を張出す。地方医院の生活様式を反映している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013129"},{"id":"00013131","register_sub_id":"101","register_pk":"368287","name":"旧常喜医院西蔵","kana":"きゅうじょうきいいんにしのくら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34764444,"lng":136.35410833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0445","desc":"主屋の北側に東面して建つ。東西棟の切妻造桟瓦葺、土蔵造二階建で、戸口前に下屋を設ける。外壁は東蔵と同様に、上部を漆喰塗、水切下を竪板張とする。内部は一、二階とも西側から一間の位置に片引戸を立て仕切る。屋敷北側背面の景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013131"},{"id":"00013130","register_sub_id":"101","register_pk":"368286","name":"旧常喜医院東蔵","kana":"きゅうじょうきいいんひがしのくら","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県米原市堂谷字北小路212","lat":35.34762222,"lng":136.35434722,"geo_status":"db","era":"大正4年／昭和前期移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積21㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"25 － 0444","desc":"主屋の北東に南面して建つ。東西棟の切妻造桟瓦葺、土蔵造二階建で、平入の戸口前に桟瓦葺の下屋を設ける。外壁は上部を漆喰塗、水切下を竪板張とする。内部は一、二階とも一室で、内壁は柱間に板を落し込む。西蔵とともに背面の屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013130"},{"id":"00002410","register_sub_id":"101","register_pk":"103400","name":"旧水口図書館","kana":"きゅうみなくちとしょかん","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県甲賀市水口町本町1-2-1","lat":34.96985398,"lng":136.17589663,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積52㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0179","desc":"町の中心地，水口小学校正門脇の角地に建つ。建物の北東側に塔屋を設けた鉄筋コンクリート造２階建。正面玄関の両脇にトスカナ式オーダーを配し，上部に薄彫を施した櫛形ペディメントを掲げる。太めの軒蛇腹が全体の外観を引き締める。ヴォーリズの設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002410"},{"id":"00014856","register_sub_id":"101","register_pk":"519116","name":"江北図書館（旧伊香郡農会庁舎）","kana":"こほくとしょかん（きゅういかぐんのうかいちょうしゃ）","category":"文化福祉","subcategory":"建築物","type_guess":"図書館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字西浦1362","lat":35.50649722,"lng":136.22250278,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積255㎡","structure_material":"木造2階一部平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"25 - 0521","desc":"木ノ本駅前に位置するかつての伊香郡農会の庁舎兼公会堂。二階建寄棟造桟瓦葺の東西棟で、南に玄関、西に平屋建の台所棟を付す。二階南面は中央をわずかに外部に突出させて切妻屋根を架ける。半円アーチの縦長窓とバットレスを並べた陰影深い外観が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014856"},{"id":"00003255","register_sub_id":"101","register_pk":"104245","name":"醒井公会堂","kana":"さめがいこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県米原市醒井字新町117、117-1","lat":35.329063,"lng":136.351501,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0215","desc":"江戸時代に宿場町として栄えた醒ヶ井の町並の中に所在する。木造平屋建，寄棟造桟瓦葺で，正面と側面前よりは吹きつけ壁，他は下見板張とする。正面隅はコーナーストーン風の仕上とするなど和洋のデザイン・構法を混在させた昭和初期公民館建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003255"},{"id":"00000137","register_sub_id":"101","register_pk":"101127","name":"滋賀大学陵水会館","kana":"しがだいがくりょうすいかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市馬場1-1-1","lat":35.27735472,"lng":136.24568967,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階一部平屋建，瓦葺，建築面積292㎡","structure_material":"木造2階一部平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"25 － 0002","desc":"経済学部の前身の彦根高等商業学校同窓会館として建設された。設計はヴォーリズ。淡いクリーム色の外壁にスペイン瓦の屋根，ドア廻りのタイルによる市松模様など，スパニッシュスタイルでまとめられた外観に特徴があり，設計者の作風の一端がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000137"},{"id":"00013568","register_sub_id":"101","register_pk":"504931","name":"中川家住宅土蔵","kana":"なかがわけじゅうたくどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"主屋・住宅","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市地福寺町962","lat":35.37572222,"lng":136.27706389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0456","desc":"敷地南東に建つ能関連の衣装や道具などの収納蔵。二階建の土蔵造桟瓦葺で、西面に戸口を開く。外壁は漆喰で軒先まで塗込めて軒裏は垂木形を表し、腰に鉄板を張る。内部は板敷で、壁を竪板張とし、登梁形式の小屋組とする。敷地背面の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013568"},{"id":"00013567","register_sub_id":"101","register_pk":"504930","name":"中川家住宅能舞台","kana":"なかがわけじゅうたくのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市地福寺町962","lat":35.37582222,"lng":136.27701667,"geo_status":"db","era":"昭和6年／昭和39年増築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"25 － 0455","desc":"市南部にある能楽師の住宅。能舞台は敷地北東に建ち、南北棟で切妻造の本屋の四周に下屋を廻して北側下屋を楽屋とする。本舞台は桁行梁間共五・六メートルで、東に地謡座、北に後座と橋掛を設け、南と西に畳敷の見所を設ける。地域芸能を支えた近代能舞台。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013567"},{"id":"00000700","register_sub_id":"101","register_pk":"101690","name":"浅香山病院西病棟","kana":"あさかやまびょういんにしびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区今池町3-3-16","lat":34.58509578,"lng":135.4907486,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積271㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"27 － 0044","desc":"清水組大阪支店の設計施工。白塔棟の西端から矩折れに南に延び，創建時は女子の一等病室等にふりあてられていた。外壁面の凹凸やスカイラインに突起した塔屋小屋根などにスパニッシュに常套的なスペイン瓦の見せ所を意図的につくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000700"},{"id":"00000699","register_sub_id":"101","register_pk":"101689","name":"浅香山病院白塔","kana":"あさかやまびょういんはくとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区今池町3-3-16","lat":34.58511655,"lng":135.49125763,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造２階建塔屋付，瓦葺，建築面積627㎡","structure_material":"鉄筋コンクリート造２階建塔屋付","registered":"1998.09.02(平成10.09.02)","register_no":"27 － 0043","desc":"堺脳病院として建設。創立者の意向によりスパニッシュ・スタイルが採用された。スパニッシュのもつ明るいイメージや，白スタッコ壁の清潔さが好まれたのであろう。白塔はいわば事務所棟で，背後に平屋の病棟がパヴィリオン式に配置されていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000699"},{"id":"00001080","register_sub_id":"101","register_pk":"102070","name":"梅谷歯科医院","kana":"うめたにしかいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市西成区天下茶屋三丁目83","lat":34.6353966,"lng":135.49767447,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造３階建，スレート葺一部瓦葺，建築面積98㎡","structure_material":"木造３階建","registered":"1999.02.17(平成11.02.17)","register_no":"27 － 0057","desc":"木造３階建で道路に面して建ち，外観は１階をタイル貼り，２・３階を下見板張りとするなど洋風の意匠になる。内部は，伝統的な町家の平面を継承した形で，一部を除き和風とする。大阪の下町において洋風の意匠を積極的に取り入れた大正期建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001080"},{"id":"00000139","register_sub_id":"101","register_pk":"101129","name":"大阪倶楽部","kana":"おおさかくらぶ","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区今橋5-11","lat":34.69097102,"lng":135.49891853,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積795㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.05.07(平成9.05.07)","register_no":"27 － 0015","desc":"開口部の小さい，壁を意識させる造形が特徴的。細部装飾にはインドやイスラムの影響が見られる。関西に多くの作品を残した安井武雄の片岡事務所時代の作品で，施工は大林組。プロポーションへの意識，装飾の取り扱いなど近代建築の黎明期の作品といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000139"},{"id":"00000299","register_sub_id":"101","register_pk":"101289","name":"大阪城天守閣","kana":"おおさかじょうてんしゅかく","category":"文化福祉","subcategory":"建築物","type_guess":"城郭","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区大阪城1-1","lat":34.68734859,"lng":135.52600333,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄骨鉄筋コンクリート造8階建，建築面積1199㎡","structure_material":"鉄骨鉄筋コンクリート造8階建","registered":"1997.09.03(平成9.09.03)","register_no":"27 － 0022","desc":"陸軍用地となっていた旧本丸一帯を公園化する計画に伴い，博物館として建設された。設計は市土木局建築課，施工は大林組による。鉄筋コンクリート造，地上６階地下２階建で，市民の寄付で建設されたこともあり，大阪のシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000299"},{"id":"00010658","register_sub_id":"101","register_pk":"201232","name":"大阪市立美術館","kana":"おおさかしりつびじゅつかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市天王寺区茶臼山町115","lat":34.650057,"lng":135.510505,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄骨鉄筋コンクリート造3階地下1階建、瓦葺、建築面積4017㎡","structure_material":"鉄骨鉄筋コンクリート造3階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0613","desc":"天王寺公園の高台に建つ。正面に張出す玄関とホール部を一層分高い切妻造とし、左右の翼廊に展示室を配する。装飾を抑えた平滑で三層構成の立面を基調としつつ、壁頂の本瓦葺、蛇腹や窓の洋風装飾などに和洋の意匠を採取する。希少な戦前の大型美術館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010658"},{"id":"00006872","register_sub_id":"101","register_pk":"107854","name":"大阪大学待兼山修学館（旧大阪帝国大学医学部附属病院石橋分院本館）","kana":"おおさかだいがくまちかねやましゅうがくかん（きゅうおおさかていこくだいがくいがくぶふぞくびょういんいしばしぶんいんほんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市待兼山町1-4","lat":34.8066335,"lng":135.45169379,"geo_status":"db","era":"昭和6／平成19改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積793㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2008.03.07(平成20.03.07)","register_no":"27 － 0448","desc":"大阪府営繕課の設計による鉄筋コンクリート造３階建の病院建築。正面約８０ｍ規模で、南北に両翼を延ばした対称形の平面を採る。３階はもと病棟で、窓の外部に手摺を付ける。外観意匠は、縦長窓を規則的に配し、窓台を連続させ、庇をまわして水平線を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006872"},{"id":"00010003","register_sub_id":"101","register_pk":"196150","name":"大槻能楽堂能舞台","kana":"おおつきのうがくどうのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区上町2-1他","lat":34.67811104,"lng":135.52124786,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0579","desc":"能楽堂内に建つ能舞台。桁行梁間とも五・七メートル、切妻造妻入、檜皮葺で、右手に地謡座、背面に後座を設け、左手後方に橋掛が続く。舞台四方の頭貫上に中世風意匠の蟇股を置き、虹梁絵様や頭貫木鼻に華やかな渦紋を彫るなど、材工ともに質の高い能舞台。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010003"},{"id":"00000140","register_sub_id":"101","register_pk":"101130","name":"岸和田市立自泉会館（自泉館）","kana":"きしわだしりつじせんかいかん（じせんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市岸城町5-10","lat":34.46059811,"lng":135.37190387,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積539㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"27 － 0016","desc":"大規模な事務所建築を得意とした渡辺節の作品。彼の作品の中では比較的小規模な住宅系のものとして注目に値する。装飾の少ないシンプルな外観であるが，列柱を配した玄関部などに様式建築のモチーフが見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000140"},{"id":"00015042","register_sub_id":"101","register_pk":"529320","name":"旧朝日湯","kana":"きゅうあさひゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府泉佐野市元町4535-1","lat":34.41255,"lng":135.31433611,"geo_status":"db","era":"大正15年／令和4年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0913","desc":"孝子越街道に南面して建つ旧銭湯。片入母屋造平入桟瓦葺の脱衣場は庇中央を切上げ入口とし北に切妻造妻入桟瓦葺の浴室２棟、その北に土間の釜場を接続。西浴室は中央に御影石製の大浴槽を残し、上部はヴォールト天井を現すなど豪華なつくりの和洋折衷の銭湯。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015042"},{"id":"00011349","register_sub_id":"101","register_pk":"209186","name":"旧菅澤眼科病院","kana":"きゅうすがさわがんかびょういん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区土佐堀二丁目47-1他","lat":34.688323,"lng":135.49001,"geo_status":"db","era":"昭和4／昭和56・平成13頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積184㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0647","desc":"大阪市中心部の土佐堀地区に所在する病院建築。南東隅を四分一円として玄関ポーチを設けた平面で、外壁はタイル貼でアール・デコを基調とし、柱形を密に並べて縦長窓を配する。最上階ではアーチ窓とし、柱型に柱頭飾を施す。昭和初期の意匠的特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011349"},{"id":"00000988","register_sub_id":"101","register_pk":"101978","name":"源ケ橋温泉浴場","kana":"げんがはしおんせんよくじょう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区林寺1-37-1","lat":34.64573867,"lng":135.52901424,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造２階建，瓦葺，建築面積343㎡","structure_material":"木造２階建","registered":"1998.12.11(平成10.12.11)","register_no":"27 － 0055","desc":"平面は番台を挟んで男女別に区画され，浴槽部分は随時改修されているが，脱衣場及び浴室の構えはよく残る。外観は，屋根は茶褐色の桟瓦を葺き，正面２階には彫像付きの洋風窓や丸窓を開く。市街地における木造の公衆浴場の好例で，広く利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000988"},{"id":"00000255","register_sub_id":"101","register_pk":"101245","name":"四天王寺八角亭","kana":"してんのうじはっかくてい","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺1-11-18","lat":34.65543222,"lng":135.51820557,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積21㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"27 － 0020","desc":"第５回内国勧業博覧会の小奏楽堂として建築されたものを、後に現在地に移築したと伝える。平面八角で、庇柱は吹き放ちとし、窓には色ガラスをはめる。母屋柱はコリント式の柱頭飾を付け、モールディングの廻り縁を巡らすなど施工技術にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000255"},{"id":"00010681","register_sub_id":"101","register_pk":"201255","name":"島本町立歴史文化資料館（旧麗天館）","kana":"しまもとちょうりつれきしぶんかしりょうかん（きゅうれいてんかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府三島郡島本町桜井1-3-1","lat":34.880071,"lng":135.663699,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積421㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0636","desc":"駅前に建つ武徳殿風の大型木造建築。入母屋造桟瓦葺で裳階を廻らし、入母屋屋根の玄関を構える。側廻りは柱上に舟肘木を載せ、腰板を張る。内部は主体部を広いホールとして折上格天井を張り、片側に演壇を設ける。社寺建築の工法を援用した風格ある会堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010681"},{"id":"00014265","register_sub_id":"101","register_pk":"509655","name":"杉江能楽堂","kana":"すぎえのうがくどう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府岸和田市岸城町1909-3","lat":34.46126667,"lng":135.37172778,"geo_status":"db","era":"大正6年／昭和42年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積283㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0856","desc":"岸和田城跡に所在する能楽堂。切妻造の舞台棟と、橋掛り含む楽屋棟を白洲中庭に面して配し、相対する入母屋造座敷棟の見所と、下手の脇見所からなる。見所は床構え付十畳二間、脇見所は六畳間。対置式で白洲に採光するのは希少で、大阪府内現存最古の能楽堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014265"},{"id":"00000989","register_sub_id":"101","register_pk":"101979","name":"住吉神社能舞台","kana":"すみよしじんじゃのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府豊中市服部南町2-3-31","lat":34.76294729,"lng":135.47889793,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積66㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"27 － 0056","desc":"大阪博物場の観能施設として造られた能舞台で，天満宮を経て住吉神社が所有する。総桧造の伝統的形式に則って造られている。設計は大阪府技手岡崎要吉，工事監督井上節，棟梁は京都の雑賀長右衛門で，当時の上方大工の技術水準の高さを示す作品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000989"},{"id":"00012590","register_sub_id":"101","register_pk":"504379","name":"大将軍湯","kana":"だいしょうぐんゆ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市本町4733-2","lat":34.415081,"lng":135.315353,"geo_status":"geocoded","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積139㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0763","desc":"市中心部の共同浴場。通りに面する表棟は中央に唐破風の玄関を構え、左右塀の腰をタイル張とする。後方の浴室棟は吹抜けの一空間で、中央の浴槽を男湯･女湯の境壁で二分する。浴槽と床の石敷に大ぶりの花崗岩を用いるのは珍しい。戦前の銭湯建築の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012590"},{"id":"00001527","register_sub_id":"101","register_pk":"102517","name":"鯛よし百番","kana":"たいよしひゃくばん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市西成区山王3-5-25","lat":34.64262152,"lng":135.50569438,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、瓦葺、建築面積291㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"27 － 0086","desc":"旧飛田新地の角地に建つ。木造２階建，入母屋造，桟瓦葺で，２階に擬宝珠高欄を巡らし，角を隅切りとして玄関に唐破風を付ける。内部は，日光東照宮陽明門を模すなど各部屋毎に趣向を凝らし，大阪歓楽街の殷賑を色濃く今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001527"},{"id":"00005702","register_sub_id":"101","register_pk":"106690","name":"通天閣","kana":"つうてんかく","category":"文化福祉","subcategory":"その他工作物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市浪速区恵美須東1-18-6","lat":34.652561,"lng":135.506348,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":null,"structure_material":null,"registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0415","desc":"難波の東南に位置する。脚部をＳＲＣ造とした１０３ｍ高の鉄塔で，塔の東側には円筒形の補助塔を設ける。四角形から八角形に平面形状が変化する塔身に独特な形状の展望台を戴き，四周に広告用等の施設を付設し，大阪のシンボルとして広く親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005702"},{"id":"00007645","register_sub_id":"101","register_pk":"108627","name":"桃花塾教室棟","kana":"とうかじゅくきょうしつとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府富田林市大字喜志2067-5他","lat":34.52416363,"lng":135.59974094,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0525","desc":"本館の東方、少し低い位置に建つ。桁行１９ｍ梁間７．６ｍと南北に長い木造平屋建、寄棟造桟瓦葺。西側に廊下を通し、東側に教室３室と便所を並べる。西面は腰竪板壁で、各柱間に引違ガラス戸をたて、明るく開放的に造る。簡素な造りの中に温もりが感じられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007645"},{"id":"00007644","register_sub_id":"101","register_pk":"108626","name":"桃花塾本館","kana":"とうかじゅくほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府富田林市大字喜志2067-5他","lat":34.52421039,"lng":135.59940847,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積214㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0524","desc":"丘陵地の緩い傾斜地に南面して建つ。木造２階建、寄棟造桟瓦葺。１階は中廊下で研究室や図書室、事務室、２階に講堂や拝礼室等を配する。正面は中央に玄関ポーチを設け、壁は下見板張とし、窓を大きくとる。緑の多い敷地環境に調和した、簡明で良質な福祉施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007644"},{"id":"00005953","register_sub_id":"101","register_pk":"106938","name":"山本能楽堂及び能舞台","kana":"やまもとのうがくどうおよびのうぶたい","category":"文化福祉","subcategory":"建築物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区徳井町1-3-6","lat":34.683937,"lng":135.514984,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"能楽堂 木造2階一部3階建、瓦葺、建築面積353㎡、能舞台 木造平屋建、檜皮葺、面積63㎡","structure_material":"能楽堂 木造2階一部3階建","registered":"2006.11.29(平成18.11.29)","register_no":"27 － 0399","desc":"街路に北面して建つ。木造２階一部３階建で，建物中央の能舞台周辺は１，２階を吹抜けとし，見所を設ける。能舞台は切妻造，檜皮葺で，東側に橋掛を設け，鏡の間と繋ぐ。楽屋等の舞台裏手の空間もよく残り，伝統的な能舞台の形式を備えた能楽堂として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005953"},{"id":"00008317","register_sub_id":"101","register_pk":"133959","name":"明石市立天文科学館","kana":"あかししりつてんもんかがくかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県明石市人丸町2-6","lat":34.64940585,"lng":135.00147122,"geo_status":"db","era":"昭和35年／昭和59年・平成10年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積1094㎡、高塔付","structure_material":"鉄筋コンクリート造4階建","registered":"2010.09.10(平成22.09.10)","register_no":"28 － 0460","desc":"鉄筋コンクリート造で、直径２３メートルの円形プラネタリウムを含む４階建の展示棟と、高さ５３メートルの高塔からなる複合建築。二重構造の高塔上部には展望室と天体観測室を備え、大時計が日本標準時を刻む。子午線のまち明石のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008317"},{"id":"00012223","register_sub_id":"101","register_pk":"353023","name":"芦屋仏教会館","kana":"あしやぶっきょうかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県芦屋市前田町100-1","lat":34.732601,"lng":135.301744,"geo_status":"db","era":"昭和2年／平成15年曳家","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積220㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2018.03.27(平成30.03.27)","register_no":"28-679","desc":"丸紅商店社長の伊藤長兵衛の寄附により建てられた。鉄筋コンクリート造四階建で、近代建築に東洋風・印度風の細部意匠を取り入れたものとされる。外観はホールの上下に対応して三階で見切りを入れて二層構成とし、様々な意匠を破綻なくまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012223"},{"id":"00012592","register_sub_id":"101","register_pk":null,"name":"旧岡方倶楽部（小物屋会館）","kana":"きゅうおかがたくらぶ（こものやかいかん）","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市兵庫区本町二丁目3-46","lat":34.669888,"lng":135.173798,"geo_status":"geocoded","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積180㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2018.11.02(平成30.11.02)","register_no":"28 － 0697","desc":"兵庫津旧市街の町会集会所で、敷地中央に東面して建つ。鉄筋コンクリート造三階建、陸屋根で、正面のみ一階石造風、二階以上タイル張風に仕上げ、玄関ポーチ上部の壁面と頂部を僅かに出して正面性を強調する。1920年代の建築的特徴を備えた洋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012592"},{"id":"00002972","register_sub_id":"101","register_pk":"103962","name":"旧海崎医院","kana":"きゅうかいざきいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷2-455","lat":35.16581922,"lng":134.7925425,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0110","desc":"街道に東面して建つ洋風医院建築で，街道側から４畳半規模の診療室，６畳規模の療治場，４畳半の和室を配置する。診療室は竪羽目板張りで，東面には鎧戸付窓を２箇所，北面には櫛形状ペディメントのキャノピーを付け，擬洋風的な木製の重厚な軒蛇腹を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002972"},{"id":"00013293","register_sub_id":"101","register_pk":"366282","name":"旧駒ヶ林公会堂","kana":"きゅうこまがばやしこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市長田区駒ヶ林町五丁目51-2","lat":34.64885833,"lng":135.14596389,"geo_status":"db","era":"大正13年頃／昭和44年・平成19年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造2階建、建築面積138㎡、塔屋付","structure_material":"煉瓦造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"28 － 0737","desc":"長田港海岸線に平行する市道沿いに建つ公会堂。二階建で、外壁は煉瓦造、内部の柱、梁、スラブは鉄筋コンクリート造とする。左右対称のファサードに縦長窓を配し、装飾性を抑えた外観とする。用途を変えながら利用され、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013293"},{"id":"00015338","register_sub_id":"101","register_pk":"532462","name":"旧野中外科診療棟","kana":"きゅうのなかげかしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県姫路市福中町11","lat":34.83253611,"lng":134.68729444,"geo_status":"db","era":"昭和28年頃／昭和32年改修、同中期増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積86㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0830","desc":"姫路市の中心部に位置し、銀行店舗を転用した旧診療棟。通りに北面する木造２階建で正面西に階段室を張出して大窓を開け、外壁モルタル洗出仕上。一階は診療施設、二階は応接室。階段室に折鶴形照明を吊る。装飾を省いた箱型の外観がモダニズムの影響を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015338"},{"id":"00015339","register_sub_id":"101","register_pk":"532463","name":"旧野中外科病棟","kana":"きゅうのなかげかびょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県姫路市福中町11","lat":34.83258056,"lng":134.68711944,"geo_status":"db","era":"昭和29年／昭和32年増改築、同中期増築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積98㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0831","desc":"診療棟の南に位置する病室棟。木造2階建切妻造平入桟瓦葺で外壁リシン掻落仕上。一階北面中央を玄関とし、各階東西に中廊下を通して一階は個室、二階は大部屋の病室、北西に便所や浴室などを配する。銀行倉庫の転用と伝わり昭和戦後の地域医療を支えた病棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015339"},{"id":"00013151","register_sub_id":"101","register_pk":"368292","name":"コウノトリ保護増殖センター第一フライングケージ","kana":"こうのとりほごぞうしょくせんたーだいいちふらいんぐけーじ","category":"文化福祉","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市野上1314-1","lat":35.56921389,"lng":134.82551389,"geo_status":"db","era":"昭和40年／平成30年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"ドーム状鉄管造、面積339㎡","structure_material":"ドーム状鉄管造","registered":"2019.12.05(令和1.12.05)","register_no":"28 － 0718","desc":"敷地最奥の谷筋に建つコウノトリの飼育ケージ。大型の半球ドームの両脇に小型の半球ドームを接続した形で、湾曲させた鉄管フレームと金網で構成される。コウノトリ保護、増殖の先駆的試みを示す記念的建造物で、飼育ケージ発展の起点となる貴重なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013151"},{"id":"00009517","register_sub_id":"101","register_pk":"194310","name":"中崎遊園地ラヂオ塔","kana":"なかさきゆうえんちらぢおとう","category":"文化福祉","subcategory":"その他工作物","type_guess":"娯楽","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県明石市相生町1-119-5","lat":34.64453167,"lng":134.99964931,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造及び石造、高さ3.4m","structure_material":"鉄筋コンクリート造及び石造","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0556","desc":"明石海峡に面した中崎遊園地内に建つ。鉄筋コンクリート造一部石造、一辺一・二メートル、高さ三・四メートルの方形の塔で、頂部を燈籠状にしてラジオの台とし、軒反りをつけた宝形造の屋根をのせる。建設当時の社会の様相とラジオの普及の過程を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009517"},{"id":"00001443","register_sub_id":"101","register_pk":"102433","name":"白鶴美術館事務棟","kana":"はくつるびじゅつかんじむとう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73068116,"lng":135.25806451,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積301㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0058","desc":"敷地の入口側に建つ事務棟で，階下に事務室・応接室，階上に集会室，地下に荷解室等を配する。本館と同様な鉄骨鉄筋コンクリート造の和風建築であるが，寺院建築風の本館に対し，木造真壁造風の簡潔な意匠を基調とし全体にのびやかな非対称の建築構成をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001443"},{"id":"00001444","register_sub_id":"101","register_pk":"102434","name":"白鶴美術館土蔵","kana":"はくつるびじゅつかんどぞう","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73086933,"lng":135.25795397,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、鉛板葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0059","desc":"本館と事務棟を結ぶ長８間の渡廊下のほぼ中間，渡廊下の西側に建つ南北棟，２階建，切妻屋根，平入の収蔵庫で，渡廊下側の東面に入口を設ける。嘉納治兵衛の持論に基づき，鉄筋コンクリート造でなく，伝統的な木造土蔵造りによって建てられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001444"},{"id":"00001442","register_sub_id":"101","register_pk":"102432","name":"白鶴美術館本館","kana":"はくつるびじゅつかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区住吉山手6-1-1","lat":34.73103242,"lng":135.25806024,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、銅板葺、建築面積526㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0057","desc":"酒造業白鶴の７代目当主嘉納治兵衛が蒐集した美術品を公開する施設で，住吉川の右岸傾斜地の高台側に南面して建つ。鉄骨鉄筋コンクリート造による純和風建築で，竹中工務店の設計施工になり，鷲尾九郎が設計を担当したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001442"},{"id":"00012430","register_sub_id":"101","register_pk":"531754","name":"御影公会堂","kana":"みかげこうかいどう","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市東灘区御影石町四丁目73-1","lat":34.71606944,"lng":135.2492,"geo_status":"db","era":"昭和8年／昭和26年・同47年・平成16年・同29年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造3階建地下1階、建築面積1032㎡","structure_material":"鉄筋コンクリート造3階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"28-687","desc":"国道二号と石屋川が交差する御影地区の中心地に建つ。嘉納治兵衛の寄附、清水栄二の設計、大林組の施工により、モダニズムを基調に多様な造形表現を取込み、全体を巧みにまとめる。様々な用途で活用され地域に親しまれてきた、独創的な意匠の文化施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012430"},{"id":"00006614","register_sub_id":"101","register_pk":"107597","name":"旧小國家住宅診療所","kana":null,"category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県神崎郡福崎町山崎字大将軍814","lat":34.96852176,"lng":134.755386,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"28 － 0300","desc":"主屋の東側に隣接し、東西棟で建つ。桁行４間半梁間３間規模、切妻造桟瓦葺の木造平屋建で、西方を待合室として切妻造の玄関を突出させ、東北には手術室を張り出す。正面東方は庇を出して全面ガラス窓とする。当地域における地域医療施設の状況が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006614"},{"id":"00005337","register_sub_id":"101","register_pk":"106325","name":"杉山小児科医院住居棟","kana":"すぎやましょうにかいいんじゅうきょとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市本町52","lat":34.65125062,"lng":135.78505289,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、銅板葺、建築面積92㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0096","desc":"木造２階建，寄棟造，銅板葺，妻入で，東に診療棟が接続する。外壁は１階がタイル張，２階が人造石洗い出し仕上げでフリーズ状の飾りをつけ，窓は上げ下げ式の縦長窓とする。診療棟と異なるアールデコ風意匠は当時の造形の傾向を示し，景観上，存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005337"},{"id":"00005336","register_sub_id":"101","register_pk":"106324","name":"杉山小児科医院診療棟","kana":"すぎやましょうにかいいんしんりょうとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県大和郡山市本町52","lat":34.6512481,"lng":135.78517907,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、瓦葺、建築面積170㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0095","desc":"街路に北面して建ち，西に居住棟が続く。東西棟の切妻造，平入，平屋建で，中央部は棟が直交した２階建として外壁を立ち上げる。外観はハーフティンバースタイルで，屋根窓や玄関庇など変化に富む。伝統的な町並みにあって，ランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005336"},{"id":"00014904","register_sub_id":"101","register_pk":"519164","name":"手貝町会所","kana":"てがいちょうかいしょ","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市雑司町79他","lat":34.69263056,"lng":135.83514722,"geo_status":"db","era":"昭和14年／昭和51年・平成13年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"29 - 0357","desc":"東大寺転害門の北の住宅地に建つ集会所。平屋建切妻造桟瓦葺で南面西寄りに入母屋造玄関を付す。内部東は床構え付きの大広間で南東隅に付書院を備え、西は小会議室と物置を配す。小屋組はキングポスト・トラス。四十畳の広間を有し、地域住民が親しむ集会所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014904"},{"id":"00016423","register_sub_id":"101","register_pk":"536490","name":"奈良文化財研究所飛鳥資料館売札所","kana":"ならぶんかざいけんきゅうしょあすかしりょうかんばいさつしょ","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"奈良県","address":"奈良県桜井市大字山田681","lat":34.48365278,"lng":135.82571667,"geo_status":"db","era":"昭和50年／昭和52年改修","year":1975,"year_source":"db","year_min":1975,"year_max":1975,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積29㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"29 - 0374","desc":"資料館の正門東脇に建つ売札所。設計は谷口吉郎。鉄筋コンクリート造平屋建切妻造桟瓦葺の南北棟で、正面となる南妻は売札口の庇を兼ね螻羽を深くして切妻屋根を強調する。本館と共通する均整の取れた端正な外観で、本館と一体となって歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016423"},{"id":"00016422","register_sub_id":"101","register_pk":"536489","name":"奈良文化財研究所飛鳥資料館本館","kana":"ならぶんかざいけんきゅうしょあすかしりょうかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"奈良県","address":"奈良県高市郡明日香村大字奥山601他","lat":34.48432222,"lng":135.82516111,"geo_status":"db","era":"昭和49年","year":1974,"year_source":"db","year_min":1974,"year_max":1974,"year_label":null,"structure":"鉄筋コンクリート造地上1階地下1階建、瓦葺、建築面積1，182㎡","structure_material":"鉄筋コンクリート造地上1階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"29 - 0373","desc":"明日香村の北部にある文化財展示施設。設計は谷口吉郎。鉄筋コンクリート造地上1階地下1階建。切妻造の東西棟を前後に配し、外壁に格子窓を整然と並べ、周囲に高欄付縁を廻らす。洗練された和風の外観が、飛鳥地域の歴史的な景観と調和する谷口晩期の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016422"},{"id":"00012783","register_sub_id":"101","register_pk":"367686","name":"野村医院旧診療所","kana":"のむらいいんきゅうしんりょうじょ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県山辺郡山添村大字大西294","lat":34.681325,"lng":136.04389444,"geo_status":"db","era":"明治30年頃／昭和31年移築・改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"29 － 278","desc":"村中心部のもと診療所。木造平屋建、入母屋造桟瓦葺妻入で、南面西半に切妻造の車寄を付す。外壁は漆喰塗の腰下見板張、側面に引分け硝子窓を並べる。内部は2列6室で、待合室や診察室、手術室等を機能的に配する。明治期の地方診療施設の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012783"},{"id":"00008322","register_sub_id":"101","register_pk":"133964","name":"松浦家住宅旧診察室","kana":"まつうらけじゅうたくきゅうしんさつしつ","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.59880659,"lng":135.70410779,"geo_status":"db","era":"昭和21年／昭和30年改修","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0193","desc":"主屋の南に接続する木造平屋建。外壁モルタル仕上げで、四隅に柱型をつくり、パラペットをまわす。主屋との取り付き部分を含め、南北６．８ｍ東西３．２ｍ。東面北寄りに出入口を開け、南を診察室とした。入口内部の壁には円窓を穿ち、緑色ガラスを嵌める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008322"},{"id":"00014198","register_sub_id":"101","register_pk":"508828","name":"紀伊風土記の丘松下記念資料館","kana":"きいふどきのおかまつしたきねんしりょうかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県和歌山市岩橋1411","lat":34.22789444,"lng":135.22961389,"geo_status":"db","era":"昭和46年／平成13年改修","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄筋コンクリート造平屋建地階付、建築面積1，593㎡","structure_material":"鉄筋コンクリート造平屋建地階付","registered":"2022.02.17(令和4.02.17)","register_no":"30-0318","desc":"古墳群の傍らに建つ浦辺鎮太郎設計の鉄筋コンクリート造博物館施設。土塁等で設計条件のボリュームを抑えた外観を実現する。大面取りピラスター、長押形水切、青石貼りの壁、銅鐸文様面格子など古代から着想を得て、モダニズムを基調としつつ景観に溶け込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014198"},{"id":"00004286","register_sub_id":"101","register_pk":"105276","name":"火伏医院病院棟","kana":"ひぶせいいんびょういんとう","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県橋本市橋本1-16、1-17","lat":34.31638904,"lng":135.61198981,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"30 － 0057","desc":"主屋の西に位置し，街道から退いて建つ。６．７ｍ角の平面規模，木造２階建，下見板張で，屋根は桟瓦葺とし正面側を寄棟，背面側を切妻につくる。紀ノ川の洪水に配慮して１．３ｍ程の高床としている点に特徴があり，橋本の町並みのランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004286"},{"id":"00013175","register_sub_id":"101","register_pk":"368404","name":"南方熊楠記念館本館","kana":"みなかたくまぐすきねんかんほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県西牟婁郡白浜町字崎の北3601-1","lat":33.69372778,"lng":135.33628889,"geo_status":"db","era":"昭和40年／平成29年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積240㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0278","desc":"番所山の最高地点に建つ鉄筋コンクリート造二階建の記念館。緩い糸巻き型の細長い平面を北東の田辺湾に向けて眺望を取り、南面を正面とする。正面二階は腕木を手前に張り出させ、丸みを帯びたコンクリート斫り仕上の量感のある庇で特徴的な立面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013175"},{"id":"00012974","register_sub_id":"101","register_pk":"368053","name":"三輪崎青年会館","kana":"みわさきせいねんかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県新宮市三輪崎二丁目498-3他","lat":33.685575,"lng":135.98536389,"geo_status":"db","era":"昭和2年／平成13年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積194㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 261","desc":"町中心部の通りに南面して建つ集会施設。木造平屋建、切妻造桟瓦葺妻入で、正面妻に日の出の浮彫を施し、両端の突出部にペディメントを載せる。内部は一空間で、北側に舞台、南側に桟敷状の二階を設ける。三輪崎漁港の街路景観のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012974"},{"id":"00004994","register_sub_id":"101","register_pk":"105984","name":"革島医院","kana":"かわしまいいん","category":"文化福祉","subcategory":"建築物","type_guess":"病院・診療","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区麩屋町通六角下る坂井町468-1","lat":35.00656262,"lng":135.76583886,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造3階建、瓦葺、建築面積376㎡","structure_material":"木造3階建","registered":"2005.11.10(平成17.11.10)","register_no":"26 － 0203","desc":"市役所の南西，麩屋町通に西面して建つ住宅兼病院。ロ字形平面を基本とした木造３階建でフランス瓦を使用。北西端に円錐形屋根を架したタイル張の円筒形塔屋，正面南寄りには格子窓を垂直方向に連ね妻をハーフティンバーとした階段室を張出すなど独特の外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004994"},{"id":"00000544","register_sub_id":"101","register_pk":"101534","name":"関西日仏学館","kana":"かんさいにちふつがっかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区吉田泉殿町8-8","lat":35.0262482,"lng":135.77827269,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造地上３階地下１階建，建築面積549㎡","structure_material":"鉄筋コンクリート造地上３階地下１階建","registered":"1998.04.21(平成10.04.21)","register_no":"26 － 0013","desc":"２０世紀フランスを代表する建築家ペレの弟子メストラレが基本設計にあたる。ペレ流の洗練された柱型と軒線がつくる古典主義的骨格に，要所の曲面が優美さを与える。東大路通に面して建ち，京都大学の諸建築とともに学園街を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000544"},{"id":"00011343","register_sub_id":"101","register_pk":"209180","name":"関西美術院","kana":"かんさいびじゅついん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市左京区岡崎南御所町41","lat":35.01559,"lng":135.785054,"geo_status":"db","era":"明治39／明治40増築、昭和37・同39改修","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積244㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"26－0507","desc":"洋画の普及・指導のために設立された関西美術院の建物。設計は武田五一。木造平屋建で、トラス組で緩勾配の片流屋根をかける。北面には大きな窓を設け、アトリエに最適な採光を確保している。我が国でアトリエ空間を設けた建築の初期の事例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011343"},{"id":"00002293","register_sub_id":"101","register_pk":"103283","name":"祇園甲部歌舞練場玄関","kana":"ぎおんこうぶかぶれんじょうげんかん","category":"文化福祉","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001949,"lng":135.775299,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0085","desc":"東側本館，南側別館，北側の弥栄会館に囲まれた位置に建ち，演舞会時には一等玄関・一等待合に使用されてきた。入母屋造の主体部に唐破風の車寄を接続した形態で，主体部は４５畳と３０畳の板間に分かれていた。入口に相応しい堂々とした外観を備えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002293"},{"id":"00002294","register_sub_id":"101","register_pk":"103284","name":"祇園甲部歌舞練場正門","kana":"ぎおんこうぶかぶれんじょうせいもん","category":"文化福祉","subcategory":"建築物","type_guess":"門・塀","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001663,"lng":135.775009,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積174㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0086","desc":"祇園甲部歌舞練場は，明治６年に杉浦治郎右衛門が新しい歌舞芸能として考案した「都踊り」開催場として建設したことに始まる。鉄筋コンクリート造，平屋建，寄棟造・銅板瓦葺の建物で，敷地西側の花見小路に面して建ち，アプローチを構成する重要な要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002294"},{"id":"00002292","register_sub_id":"101","register_pk":"103282","name":"祇園甲部歌舞練場別館","kana":"ぎおんこうぶかぶれんじょうべっかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.001266,"lng":135.77594,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積712㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0084","desc":"本館の南側に接する東西棟・妻入の細長い建物で，１階は当初７０畳敷の点茶席，２階は休憩室・待合室で床・棚付の２室とする。正面となる西面は車寄の唐破風，玄関となる妻庇上の千鳥破風，入母屋造の妻飾が階段状に続き，躍動感のある外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002292"},{"id":"00002291","register_sub_id":"101","register_pk":"103281","name":"祇園甲部歌舞練場本館","kana":"ぎおんこうぶかぶれんじょうほんかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区祇園町南側570-2","lat":35.00141637,"lng":135.77586118,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造地上2階一部地下1階建、瓦葺、建築面積1035㎡","structure_material":"木造地上2階一部地下1階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0083","desc":"西面して建つ木造２階建で，広大な南北棟の入母屋造・瓦葺屋根を架け，西面に千鳥破風を設ける。北側を舞台，南側を客席とした構成で，良質の檜材を用いた丁寧なつくりになる。記念的な木造の大劇場建築であり，明治期の祇園町都踊りの盛況を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002291"},{"id":"00007069","register_sub_id":"101","register_pk":"108051","name":"旧恩賜京都博物館陳列品収納用倉庫（京都国立博物館技術資料参考館）","kana":"きゅうおんしきょうとはくぶつかんちんれつひんしゅうのうようそうこ（きょうとこくりつはくぶつかんぎじゅつしりょうさんこうかん）","category":"文化福祉","subcategory":"建築物","type_guess":"博物館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区正面通本町東入茶屋町527他","lat":34.989529,"lng":135.773697,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、瓦葺、建築面積101㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0291","desc":"本館東南の高台に建つ。寄棟造桟瓦葺。鉄筋コンクリート造２階地下１階建、東西に長い矩形平面で、西面に庇付の玄関を設ける。スクラッチタイル貼とし、柱や梁の構造を表し、南面に大きく方形の窓、北面に縦型窓を各階に開け、端正でリズム感ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007069"},{"id":"00002296","register_sub_id":"101","register_pk":"103286","name":"旧弥栄会館","kana":"きゅうやさかかいかん","category":"文化福祉","subcategory":"建築物","type_guess":"会館","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区四条通大和大路東入祇園町南側570-289","lat":35.001785,"lng":135.775482,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上5階地下1階建、瓦葺、建築面積260㎡、西面及び南面東寄り外壁付","structure_material":"鉄骨鉄筋コンクリート造地上5階地下1階建","registered":"2001.08.28(平成13.08.28)","register_no":"26 － 0088","desc":"鉄骨鉄筋コンクリート造，地上５階地下１階建で，南面して建つ。各階に銅板瓦葺屋根をかけ，塔屋状の正面中央部は付庇や宝形造屋根が城郭の天守を思わせる造形で，和風意匠の伝統を巧みに織り込んでいる。設計は劇場建築を手がけた木村得三郎，施工は大林組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002296"}];
